87	    {
88	      for (i = 0; i + start <= n; i++)
89	        {
90	          s[i] = s[i + start];
91	        }
92	    }
93	}
94	
95	static void remove_tail(char *s, size_t cut)
96	{
97	  size_t n = strlen(s);
98	
99	  if (cut >= n)
100	    {
101	      s[0] = '\0';
102	      return;
103	    }
104	
105	  s[n - cut] = '\0';
106	}
107	
108	/* Fillers are stripped from the ends only.  A middle substring may be part of
109	 * a point name, and cutting it would silently ask about a different point. */
110	
111	static const char *const k_prefix[] =
112	{
113	  "请问", "麻烦", "帮我看看", "帮我查", "帮我", "帮忙", "我想知道", "我想问",
114	  "查一下", "查查", "看一下", "看看", "告诉我", "现在", "当前", "目前",
115	  NULL
116	};
117	
118	static const char *const k_suffix[] =
119	{
120	  "是多少", "是多少呢", "多少", "是几", "读数", "数值", "现在的值", "当前的值",
121	  "的值", "值", "现在", "当前", "怎么样", "如何",
122	  "恢复了吗", "恢复没有", "恢复了没有", "恢复", "解除了吗", "解除",
123	  "消除了吗", "消除", "正常了吗", "正常了没", "正常没有", "正常么",
124	  "好了吗", "好了没有", "好了没", "好了", "还报吗", "还在报吗", "还报警吗", "还在报警吗",
125	  "报警吗", "告警吗", "异常吗", "还在吗",
126	  "的告警", "的报警", "告警", "报警", "呢", "吗", "了", "呀", "啊", "的",
127	  NULL
128	};
129	
130	static bool strip_once(char *s)
131	{
132	  int i;
133	
134	  for (i = 0; k_prefix[i] != NULL; i++)
135	    {
136	      if (starts_with(s, k_prefix[i]))
137	        {
138	          size_t cut = strlen(k_prefix[i]);
139	
140	          memmove(s, s + cut, strlen(s + cut) + 1);
141	          trim(s);
142	          return true;
143	        }
144	    }
145	
146	  for (i = 0; k_suffix[i] != NULL; i++)
147	    {
148	      if (ends_with(s, k_suffix[i]))
149	        {
150	          remove_tail(s, strlen(k_suffix[i]));
151	          trim(s);
152	          return true;
153	        }
154	    }
155	
156	  return false;
157	}
158	
159	int vg_vi_point_token(const char *text, char *out, size_t cap)
160	{
161	  char buf[128];
162	  int guard;
163	
164	  if (out == NULL || cap == 0)
165	    {
166	      return 0;
167	    }
168	
169	  out[0] = '\0';
170	
171	  if (text == NULL || text[0] == '\0' || strlen(text) >= sizeof(buf))
172	    {
173	      return 0;
174	    }
175	
176	  snprintf(buf, sizeof(buf), "%s", text);
177	  trim(buf);
178	
179	  /* Bounded: each pass removes at least one byte, and the guard keeps a
180	   * pathological suffix list from spinning. */
181	
182	  for (guard = 0; guard < 24 && buf[0] != '\0'; guard++)
183	    {
184	      if (!strip_once(buf))
185	        {
186	          break;
187	        }
188	    }
189	
190	  if (strlen(buf) >= cap)
191	    {
192	      return 0;
193	    }
194	
195	  snprintf(out, cap, "%s", buf);
196	  return (int)strlen(out);
197	}
198	
199	int vg_vi_normalize_digits(const char *in, char *out, size_t cap)
200	{
201	  static const struct
202	  {
203	    const char *from;
204	    char        to;
205	  } map[] =
206	  {
207	    { "零", '0' }, { "〇", '0' }, { "幺", '1' }, { "一", '1' },
208	    { "二", '2' }, { "两", '2' }, { "三", '3' }, { "四", '4' },
209	    { "五", '5' }, { "六", '6' }, { "七", '7' }, { "八", '8' },
210	    { "九", '9' }
211	  };
212	
213	  size_t o = 0;
214	  size_t i = 0;
215	
216	  if (out == NULL || cap == 0)
217	    {
218	      return 0;
219	    }
220	
221	  out[0] = '\0';
222	
223	  if (in == NULL)
224	    {
225	      return 0;
226	    }
227	
228	  while (in[i] != '\0')
229	    {
230	      size_t k;
231	      bool replaced = false;
232	
233	      for (k = 0; k < sizeof(map) / sizeof(map[0]); k++)
234	        {
235	          size_t fl = strlen(map[k].from);
236	
237	          if (strncmp(in + i, map[k].from, fl) == 0)
238	            {
239	              if (o + 1 >= cap)
240	                {
241	                  out[0] = '\0';
242	                  return 0;
243	                }
244	
245	              out[o++] = map[k].to;
246	              i += fl;
247	              replaced = true;
248	              break;
249	            }
250	        }
251	
252	      if (replaced)
253	        {
254	          continue;
255	        }
256	
257	      if (o + 1 >= cap)
258	        {
259	          out[0] = '\0';
260	          return 0;
261	        }
262	
263	      out[o++] = in[i++];
264	    }
265	
266	  out[o] = '\0';
267	  return (int)o;
268	}
269	
270	/* ── classification ─────────────────────────────────────────────── */
271	
272	/* Words that ask for a change.  The voice path cannot perform any of them, so
273	 * the answer is a refusal rather than a point reading that happens to share a
274	 * word.  Erring toward refusal is safe: it never changes device state. */
275	
276	static const char *const k_control[] =
277	{
278	  "设置", "修改", "改成", "改到", "改为", "写入", "写值", "清除", "清掉",
279	  "删除", "删掉", "关闭", "打开", "开启", "启动", "停止", "控制", "重启",
280	  "配置", "添加", "新增", "应用", "下发", "设为", "调到", "切换", "调节",
281	  "调整", "重置", "复位", "设为", "输出", "打开", "关掉", "开一下",
282	  NULL
283	};
284	
285	static bool is_control(const char *text)
286	{
287	  int i;
288	
289	  for (i = 0; k_control[i] != NULL; i++)
290	    {
291	      if (has(text, k_control[i]))
292	        {
293	          return true;
294	        }
295	    }
296	
297	  return false;
298	}
299	
300	static bool is_recovery(const char *text)
301	{
302	  return has(text, "恢复") || has(text, "解除") || has(text, "好了") ||
303	         has(text, "还报") || has(text, "还在报") || has(text, "仍然报") ||
304	         has(text, "还报警") || has(text, "没恢复") || has(text, "恢复了没") ||
305	         has(text, "消除") || has(text, "消了") || has(text, "还在吗") ||
306	         has(text, "正常了吗") || has(text, "正常了没") ||
307	         has(text, "正常没有") || has(text, "正常么");
308	}
309	
310	static bool is_anomaly(const char *text)
311	{
312	  return has(text, "异常") || has(text, "告警") || has(text, "报警") ||
313	         has(text, "故障") || has(text, "问题") || has(text, "哪些点") ||
314	         has(text, "报警点");
315	}
316	
317	enum vg_voice_intent vg_vi_classify(const char *text,
318	                                    struct vg_voice_intent_result *out)
319	{
320	  enum vg_voice_intent intent = VG_VI_UNKNOWN;
321	
322	  if (out != NULL)
323	    {
324	      memset(out, 0, sizeof(*out));
325	    }
326	
327	  if (text == NULL || text[0] == '\0')
328	    {
329	      return VG_VI_UNKNOWN;
330	    }
331	
332	  if (is_control(text))
333	    {
334	      intent = VG_VI_REFUSED;
335	    }
336	  else if (is_recovery(text))
337	    {
338	      intent = VG_VI_RECOVERY;
339	    }
340	  else if (is_anomaly(text))
341	    {
342	      intent = VG_VI_ANOMALY;
343	    }
344	  else
345	    {
346	      /* A bare point name is a read request in this UI.  Whether the name
347	       * exists is decided by the table lookup, not here. */
348	
349	      intent = VG_VI_POINT;
350	    }
351	
352	  if (out != NULL)
353	    {
354	      out->intent = intent;
355	
356	      if (intent == VG_VI_POINT || intent == VG_VI_RECOVERY)
357	        {
358	          out->has_token =
359	              vg_vi_point_token(text, out->token, sizeof(out->token)) > 0;
360	        }
361	    }
362	
363	  return intent;
364	}
365	
366	/* ── point resolution ───────────────────────────────────────────── */
367	
368	static bool id_matches_normalized(const struct vg_agent_point *points, int n,
369	                                  const char *token,
370	                                  struct vg_agent_query_result *out)
371	{
372	  char norm[VG_AGENT_QUERY_STR_MAX];
373	  int i;
374	
375	  if (vg_vi_normalize_digits(token, norm, sizeof(norm)) <= 0)
376	    {
377	      return false;
378	    }
379	
380	  /* Only ids: normalizing digits inside a name would let 一 become 1 and
381	   * change which name the user said. */
382	
383	  for (i = 0; i < n; i++)
384	    {
385	      if (strcmp(points[i].id, norm) == 0)
386	        {
387	          memset(out, 0, sizeof(*out));
388	          out->mode = VG_AGENT_MATCH_ID;
389	          out->index = i;
390	          return true;
391	        }
392	    }
393	
394	  return false;
395	}
396	
397	enum vg_agent_query_rc
398	vg_vi_resolve_point(const char *text, const struct vg_agent_point *points,
399	                    int n, struct vg_agent_query_result *out,
400	                    char *token, size_t token_cap)
401	{
402	  char buf[VG_AGENT_QUERY_STR_MAX];
403	  enum vg_agent_query_rc rc;
404	
405	  if (token != NULL && token_cap > 0)
406	    {
407	      token[0] = '\0';
408	    }
409	
410	  if (text == NULL || points == NULL || out == NULL || n <= 0)
411	    {
412	      return VG_AGENT_QUERY_ARG;
413	    }
414	
415	  /* Exact identity wins before removing grammatical endings. */
416	  rc = vg_agent_query_match(points, n, text, out);
417	  if (rc == VG_AGENT_QUERY_AMBIG ||
418	      (rc == VG_AGENT_QUERY_OK && out->mode != VG_AGENT_MATCH_NAME_SUB))
419	    {
420	      if (token != NULL && token_cap > 0)
421	        snprintf(token, token_cap, "%s", text);
422	      return rc;
423	    }
424	
425	  if (vg_vi_point_token(text, buf, sizeof(buf)) <= 0)
426	    {
427	      return VG_AGENT_QUERY_NOT_FOUND;
428	    }
429	
430	  if (token != NULL && token_cap > 0)
431	    snprintf(token, token_cap, "%s", buf);
432	  rc = vg_agent_query_match(points, n, buf, out);
433	  if ((rc == VG_AGENT_QUERY_OK && out->mode != VG_AGENT_MATCH_NAME_SUB) ||
434	      rc == VG_AGENT_QUERY_AMBIG)
435	    {
436	      if (token != NULL && token_cap > 0)
437	        {
438	          snprintf(token, token_cap, "%s", buf);
439	        }
440	
441	      return rc;
442	    }
443	
444	  if (id_matches_normalized(points, n, buf, out))
445	    {
446	      if (token != NULL && token_cap > 0)
447	        {
448	          snprintf(token, token_cap, "%s", buf);
449	        }
450	
451	      return VG_AGENT_QUERY_OK;
452	    }
453	
454	  /* The filler stripper may have cut a name that itself ends in one of the
455	   * suffix words.  Retry with the untouched sentence before saying the point
456	   * does not exist. */
457	
458	  if (strcmp(buf, text) != 0)
459	    {
460	      rc = vg_agent_query_match(points, n, text, out);
461	      if ((rc == VG_AGENT_QUERY_OK && out->mode != VG_AGENT_MATCH_NAME_SUB) ||
462	          rc == VG_AGENT_QUERY_AMBIG)
463	        {
464	          if (token != NULL && token_cap > 0)
465	            {
466	              snprintf(token, token_cap, "%s", text);
467	            }
468	
469	          return rc;
470	        }
471	    }
472	
473	  return VG_AGENT_QUERY_NOT_FOUND;
474	}
475	
476	
477	bool vg_vi_is_followup(const char *text)
478	{
479	  char token[VG_AGENT_QUERY_STR_MAX];
480	  if (vg_vi_point_token(text, token, sizeof(token)) <= 0) return false;
481	  return strcmp(token, "它") == 0 || strcmp(token, "那它") == 0 ||
482	         strcmp(token, "这个点位") == 0 || strcmp(token, "该点位") == 0 ||
483	         strcmp(token, "刚才那个点位") == 0;
484	}
