54	/* The worker owns the whole call chain: a 4 KB response buffer, the 4 KB body
55	 * piece and the 2 KB TLS read buffer inside the transport, the TLS handshake,
56	 * and the render buffers.  16 KB was not enough headroom for that stack. */
57	
58	/* mbedTLS handshake plus the ASR body builder measured around 10 KB of frame
59	 * at the fault site, but the handshake's deepest path is not observable from
60	 * the dump; 48 KB leaves room for the certificate parse. */
61	#define VR_STACK_SIZE   49152
62	#define VR_PRIORITY     118
63	#define VR_TICK_MS      50
64	#define VR_AGENT_POLL_MS 10
65	#define VR_PLAY_EXTRA_MS 5000u
