67	struct voice_round
68	{
69	  bool                 started;
70	  pthread_t            thread;
71	  sem_t                wake;
72	  struct vg_voice_session s;
73	  volatile int         cancel;
74	  volatile bool        press_pending;
75	  volatile bool        submit_pending;
76	  volatile bool        end_pending;
77	  volatile bool        retry_pending;
78	  volatile bool        hold_pending;
79	  volatile bool        hold_value;
80	  volatile bool        mute_pending;
81	  volatile bool        mute_value;
