100	static uint32_t vr_now_ms(void)
101	{
102	  struct timespec ts;
103	
104	  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
105	    {
106	      return 0;
107	    }
108	
109	  return (uint32_t)((uint64_t)ts.tv_sec * 1000u
110	                    + (uint64_t)ts.tv_nsec / 1000000u);
111	}
