113	/* Stage timing for the round.  The numbers are relative to the release
114	 * that started the budget, so the gaps between the stages show up in the
115	 * serial log instead of only in the total. */
116	
117	static uint32_t vr_elapsed_ms(void)
118	{
119	  uint32_t now = vr_now_ms();
120	
121	  if (g_vr.s.submit_ms == 0 || now < g_vr.s.submit_ms)
122	    {
123	      return 0;
124	    }
125	
126	  return now - g_vr.s.submit_ms;
127	}
