145	static void vr_ui_publish(void)
146	{
147	  struct vg_voice_session *s = &g_vr.s;
148	  uint32_t now = vr_now_ms();
149	
150	  pthread_mutex_lock(&g_vr.ui_lock);
151	  g_vr.ui.generation = s->generation;
152	  g_vr.ui.state = (uint32_t)s->state;
153	  g_vr.ui.muted = s->muted;
154	  g_vr.ui.speech_failed = s->speech_failed;
155	  g_vr.ui.record_left_ms =
156	      (s->state == VG_VS_RECORDING)
157	          ? (uint32_t)(VG_VS_RECORD_MAX_MS -
158	                       (now - s->record_ms > VG_VS_RECORD_MAX_MS
159	                            ? VG_VS_RECORD_MAX_MS
160	                            : now - s->record_ms))
161	          : 0;
162	  g_vr.ui.budget_left_ms = vg_vs_remaining_ms(s, now);
163	  g_vr.ui.result_left_ms = vg_vs_result_left_s(s, now) * 1000u;
164	  g_vr.ui.visible = (s->state != VG_VS_IDLE);
165	  snprintf(g_vr.ui.question, sizeof(g_vr.ui.question), "%s", s->text);
166	  /* s->answer holds the spoken summary; the overlay keeps the full display
167	   * text that was rendered from the same snapshot.  Only fall back to the
168	   * summary when no display text has been produced yet. */
169	
170	  if (!s->have_answer)
171	    {
172	      g_vr.ui.answer[0] = '\0';
173	    }
174	  else if (g_vr.ui.answer[0] == '\0')
175	    {
176	      snprintf(g_vr.ui.answer, sizeof(g_vr.ui.answer), "%s", s->answer);
177	    }
