197	/* ── button callback ────────────────────────────────────────────── */
198	
199	/* Runs in the button task.  Nothing here may block: the pipeline stages poll
200	 * the cancel flag, and the worker reads the pending event. */
201	
202	static void vr_button(const struct vg_ptt_event_record *rec, void *arg)
203	{
204	  (void)arg;
205	
206	  if (rec->type == VG_PTT_EV_BEGIN)
207	    {
208	      g_vr.asr_src[0] = '\0';
209	      g_vr.cancel = 1;
210	      g_vr.press_pending = true;
211	      sem_post(&g_vr.wake);
212	    }
213	  else if (rec->type == VG_PTT_EV_SUBMIT)
214	    {
215	      g_vr.submit_pending = true;
216	      sem_post(&g_vr.wake);
217	    }
218	}
