377	/* Build the question and the deterministic answer for one recognised text.
378	 * Returns false with a user-facing reason when the request cannot be
379	 * answered inside the three-intent contract. */
380	
381	static bool vr_build_question(const char *text, char *question, size_t qcap,
382	                              char *tool, size_t tcap,
383	                              char *tool_json, size_t jcap,
384	                              char *target_id, size_t icap,
385	                              char *reason, size_t rcap)
386	{
387	  struct vg_voice_intent_result intent;
388	  struct vg_agent_point points[VG_AGENT_QUERY_MAX];
389	  struct vg_agent_query_result res;
390	  char token[VG_AGENT_QUERY_STR_MAX];
391	  const char *point_id;
392	  int n = 0;
393	  int rc;
394	
395	  if (target_id && icap > 0)
396	    {
397	      target_id[0] = '\0';
398	    }
399	
400	  if (vg_vi_classify(text, &intent) == VG_VI_REFUSED)
401	    {
402	      snprintf(reason, rcap, "语音只能查询当前异常、点位读数和告警恢复");
403	      return false;
404	    }
405	
406	  if (intent.intent == VG_VI_UNKNOWN)
407	    {
408	      snprintf(reason, rcap, "没有听清要查什么，请再说一次");
409	      return false;
410	    }
411	
412	  if (intent.intent == VG_VI_ANOMALY)
413	    {
414	      snprintf(question, qcap,
415	               "现在有哪些异常？请调用 vg_anomaly_read 获取完整列表，"
416	               "然后简要说明。");
417	      snprintf(tool, tcap, "vg_anomaly_read");
418	      snprintf(tool_json, jcap, "{}");
419	      return true;
420	    }
421	
422	  rc = vg_agent_tools_collect(points, VG_AGENT_QUERY_MAX, &n);
423	  if (rc != VG_AGENT_QUERY_OK && rc != VG_AGENT_QUERY_NO_SAMPLE)
424	    {
425	      snprintf(reason, rcap, "已确认点表不可读，无法查询");
426	      return false;
427	    }
428	
429	  if (n <= 0)
430	    {
431	      snprintf(reason, rcap, "还没有已确认点位");
432	      return false;
433	    }
434	
435	  rc = vg_vi_resolve_point(text, points, n, &res, token, sizeof(token));
436	
437	  if (rc == VG_AGENT_QUERY_AMBIG)
438	    {
439	      snprintf(reason, rcap, "有多个点位匹配，请报点位 ID");
440	      return false;
441	    }
442	
443	  if (rc == VG_AGENT_QUERY_NOT_FOUND && vg_vi_is_followup(text))
444	    {
445	      point_id = vg_vs_context_point(&g_vr.s);
446	      if (point_id == NULL || point_id[0] == '\0')
447	        {
448	          snprintf(reason, rcap, "请先报点位 ID 或完整名称");
449	          return false;
450	        }
451	    }
452	  else if (rc == VG_AGENT_QUERY_OK)
453	    {
454	      point_id = points[res.index].id;
455	      vg_vs_set_context_point(&g_vr.s, point_id, vr_now_ms());
456	    }
457	  else
458	    {
459	      snprintf(reason, rcap, "没有找到这个点位，请报点位 ID 或完整名称");
460	      return false;
461	    }
462	
463	  if (target_id && icap > 0)
464	    {
465	      snprintf(target_id, icap, "%s", point_id);
466	    }
467	
468	  if (intent.intent == VG_VI_RECOVERY)
469	    {
470	      snprintf(question, qcap,
471	               "查询点位 %s 的告警是否已经恢复，请调用 vg_alarm_recovery。",
472	               point_id);
473	      snprintf(tool, tcap, "vg_alarm_recovery");
474	      snprintf(tool_json, jcap, "{\"point_id\":\"%s\"}",
475	               point_id);
476	    }
477	  else
478	    {
479	      snprintf(question, qcap,
480	               "查询点位 %s 的当前读数，请调用 vg_point_read。",
481	               point_id);
482	      snprintf(tool, tcap, "vg_point_read");
483	      snprintf(tool_json, jcap, "{\"query\":\"%s\"}",
484	               point_id);
485	    }
486	
487	  return true;
488	}
