490	/* Both display and speech use the private snapshot captured for this read. */
491	static bool vr_render_answer(const struct vg_voice_facts *f, char *display,
492	                             size_t dcap, char *speech, size_t scap)
493	{
494	  if (f == NULL || f->seq == 0) return false;
495	  display[0] = '\0';
496	  speech[0] = '\0';
497	  if (f->has_recovery)
498	    vg_va_render_recovery(f, display, dcap, speech, scap);
499	  else if (f->has_point)
500	    vg_va_render_point(f, display, dcap, speech, scap);
501	  else
502	    vg_va_render_anomalies(f, display, dcap, speech, scap);
503	  return true;
504	}
