515	static void vr_log_cancel_settled(void)
516	{
517	  uint32_t started=__atomic_load_n(&g_vr.end_requested_ms,__ATOMIC_RELAXED);
518	  if (!started || g_vr.s.state != VG_VS_IDLE || vg_voice_facts_request_active()) return;
519	  struct vg_voice_stats audio;
520	  vg_voice_get_stats(&audio);
521	  if (audio.state != VG_VOICE_IDLE || vg_voice_clip_bytes() != 0) return;
522	  __atomic_store_n(&g_vr.end_requested_ms,0,__ATOMIC_RELAXED);
523	  syslog(LOG_INFO,"[vgvoice] cancel_settled elapsed_ms=%u retained_pcm=0 controlled_active=0\n",
524	         (unsigned)(vr_now_ms()-started));
525	}
