548	/* Execute the resolved read-only tool and render the answer from the
549	 * facts it publishes.  The tool runs through the agent tool registry, so
550	 * the same permission check, rate limit and audit path apply as in a
551	 * ReAct round, and the answer never comes from the model text. */
552	
553	static uint32_t vr_answer_from_tool(uint32_t gen, const char *tool,
554	                                    const char *tool_json,
555	                                    uint32_t config_version)
556	{
557	  char display[VG_VOICE_DISPLAY_MAX];
558	  char speech[VG_VS_TEXT_MAX];
559	  struct vg_voice_facts facts;
560	  char out[2048];
561	  bool captured;
562	  int rc;
563	
564	  if (!vg_voice_facts_capture_begin(&facts))
565	    {
566	      vr_ui_error("数据查询忙，请重试");
567	      return vg_vs_agent_result(&g_vr.s, gen, false, "facts busy",
568	                                vr_now_ms());
569	    }
570	
571	  out[0] = '\0';
572	  rc = tool_registry_execute(tool, tool_json, out, sizeof(out));
573	  captured = vg_voice_facts_capture_end();
574	  syslog(LOG_INFO, "[vgvoice] intent read %s rc=%d captured=%d seq=%u\n",
575	         tool, rc, captured, (unsigned)facts.seq);
576	  vr_log_stage("facts_end");
577	  if (g_vr.cancel) return 0;
578	
579	#ifdef CONFIG_VG_BUS_DISCOVER
580	  if (vg_live_points_gen() != config_version)
581	    {
582	      vr_ui_error("点表已变更，请重新提问");
583	      return vg_vs_agent_result(&g_vr.s, gen, false, "config changed",
584	                                vr_now_ms());
585	    }
586	#endif
587	
588	  facts.config_version = config_version;
589	  if (rc != 0 || !captured ||
590	      (int32_t)(g_vr.s.deadline_ms - vr_now_ms()) <= 0 ||
591	      !vr_render_answer(&facts, display, sizeof(display), speech,
592	                         sizeof(speech)))
593	    {
594	      vr_ui_error("没有拿到可核对的数据，请重试");
595	      return vg_vs_agent_result(&g_vr.s, gen, false, "no facts",
596	                                vr_now_ms());
597	    }
598	
599	  /* The session keeps only a short copy for its own bookkeeping; the full
600	   * list is published to the overlay separately. */
601	
602	  pthread_mutex_lock(&g_vr.ui_lock);
603	  snprintf(g_vr.ui.answer, sizeof(g_vr.ui.answer), "%s", display);
604	  pthread_mutex_unlock(&g_vr.ui_lock);
605	
606	  return vg_vs_agent_result(&g_vr.s, gen, true, speech, vr_now_ms());
607	}
608	
609	static uint32_t vr_stage_agent(const char *text, uint32_t gen)
610	{
611	  char question[320];
612	  char reason[128];
613	  char tool[32];
614	  char tool_json[96];
615	  char target_id[48];
616	  char display[VG_VOICE_DISPLAY_MAX];
617	  char speech[VG_VS_TEXT_MAX];
618	  struct vg_voice_facts agent_facts;
619	  bool capturing = false;
620	  bool captured = false;
621	  uint32_t config_version = g_vr.s.config_version;
622	  tool[0] = '\0';
623	  tool_json[0] = '\0';
624	  target_id[0] = '\0';
625	  vr_log_stage("agent_begin");
626	
627	  if (!vr_build_question(text, question, sizeof(question), tool, sizeof(tool),
628	                         tool_json, sizeof(tool_json), target_id,
629	                         sizeof(target_id), reason, sizeof(reason)))
630	    {
631	      vr_ui_error(reason);
632	      return vg_vs_agent_result(&g_vr.s, gen, false, reason, vr_now_ms());
633	    }
634	
635	#ifdef CONFIG_VG_VOICE_DIRECT_TOOL
636	  /* The intent and the exact point are already resolved here, and the
637	   * answer is rendered from the published facts, so a model round would
638	   * only repeat that choice while spending 5 to 9 s of the 30 s budget
639	   * on the request.  The read-only tool runs directly instead. */
640	
641	  vr_ui_set_status("查询中");
642	  vr_ui_publish();
643	  vg_vs_agent_started(&g_vr.s, gen, vr_now_ms());
644	  vr_log_stage("tool_direct");
645	
646	  return vr_answer_from_tool(gen, tool, tool_json, config_version);
647	#else
648	
649	  for (;;)
650	    {
651	      int queued;
652	      if (g_vr.cancel)
653	        {
654	          if (capturing)
655	            {
656	              vg_voice_facts_capture_end();
657	            }
658	          return 0;
659	        }
660	      if ((int32_t)(g_vr.s.deadline_ms - vr_now_ms()) <= 0)
661	        {
662	          if (capturing)
663	            {
664	              vg_voice_facts_capture_end();
665	            }
666	          vr_ui_error("等待查询超时");
667	          return vg_vs_agent_result(&g_vr.s, gen, false,
668	                                    "agent queue timeout", vr_now_ms());
669	        }
670	      queued = vg_agent_round_queue_voice(question, g_vr.s.deadline_ms);
671	      if (queued == 0)
672	        {
673	          vg_voice_facts_set_config_version(config_version);
674	          capturing = vg_voice_facts_capture_request(&agent_facts,
675	                          vg_agent_round_voice_serial(), config_version);
676	          break;
677	        }
678	      if (queued != -EBUSY)
679	        {
680	          if (capturing)
681	            {
682	              vg_voice_facts_capture_end();
683	            }
684	          vr_ui_error("查询暂不可用，请稍后再试");
685	          return vg_vs_agent_result(&g_vr.s, gen, false,
686	                                    "agent unavailable", vr_now_ms());
687	        }
688	
689	      /* Keep the one pending voice question within its original budget.
690	       * The background owner finishes and consumes its own result. */
691	      vr_ui_set_status("等待后台任务");
692	      vr_ui_publish();
693	      vg_agent_round_tick();
694	      usleep(VR_AGENT_POLL_MS * 1000u);
695	    }
696	
697	  vr_ui_set_status("查询中");
698	  vr_ui_publish();
699	  vr_log_stage("agent_queued");
700	
701	  vg_vs_agent_started(&g_vr.s, gen, vr_now_ms());
702	
703	  if (!vr_wait_agent(g_vr.s.deadline_ms))
704	    {
705	      if (capturing)
706	        {
707	          vg_voice_facts_capture_end();
708	        }
709	
710	      /* The round may still be running; its reply is discarded because the
711	       * generation no longer matches once this call returns an error. */
712	
713	      if (g_vr.cancel)
714	        {
715	          return 0;
716	        }
717	
718	      /* Give up the agent slot: otherwise the discarded round keeps the client
719	       * busy and the next question is refused for up to its 300 s timeout. */
720	
721	      vg_agent_round_abandon_owned(VG_AGENT_ROUND_OWNER_VOICE);
722	
723	      vr_ui_error((int32_t)(g_vr.s.deadline_ms - vr_now_ms()) <= 0
724	                    ? "查询超时" : "查询失败，请重试");
725	      return vg_vs_agent_result(&g_vr.s, gen, false, "agent failed",
726	                                vr_now_ms());
727	    }
728	
729	  {
730	    vg_agent_round_clear();
731	    vr_log_stage("agent_reply");
732	    if (capturing)
733	      {
734	        captured = vg_voice_facts_capture_end();
735	      }
736	    if (g_vr.cancel) return 0;
737	    if ((int32_t)(g_vr.s.deadline_ms - vr_now_ms()) <= 0)
738	      {
739	        vr_ui_error("查询超时");
740	        return vg_vs_agent_result(&g_vr.s, gen, false, "agent timeout",
741	                                  vr_now_ms());
742	      }
743	  }
744	
745	  /* If the agent tool invocation already published matching facts, reuse
746	   * them directly to save 400-800 ms of redundant tool execution. */
747	
748	  bool facts_match = false;
749	  if (captured && agent_facts.seq != 0)
750	    {
751	      if (strcmp(tool, "vg_anomaly_read") == 0)
752	        {
753	          facts_match = agent_facts.anomaly_seen > 0;
754	        }
755	      else if (strcmp(tool, "vg_alarm_recovery") == 0)
756	        {
757	          facts_match = agent_facts.has_recovery &&
758	                        agent_facts.recovery.kind == VG_RUNTIME_KIND_THRESHOLD &&
759	                        strcmp(agent_facts.recovery.id, target_id) == 0;
760	        }
761	      else if (strcmp(tool, "vg_point_read") == 0)
762	        {
763	          facts_match = agent_facts.has_point &&
764	                        strcmp(agent_facts.point_id, target_id) == 0;
765	        }
766	    }
767	
768	  if (facts_match)
769	    {
770	      syslog(LOG_INFO, "[vgvoice] reused agent facts for %s seq=%u\n",
771	             tool, (unsigned)agent_facts.seq);
772	      syslog(LOG_INFO, "[vgvoice] intent read %s rc=0 captured=1 seq=%u\n",
773	             tool, (unsigned)agent_facts.seq);
774	      vr_log_stage("facts_end");
775	
776	#ifdef CONFIG_VG_BUS_DISCOVER
777	      if (vg_live_points_gen() != config_version)
778	        {
779	          vr_ui_error("点表已变更，请重新提问");
780	          return vg_vs_agent_result(&g_vr.s, gen, false, "config changed",
781	                                    vr_now_ms());
782	        }
783	#endif
784	
785	      agent_facts.config_version = config_version;
786	      if ((int32_t)(g_vr.s.deadline_ms - vr_now_ms()) > 0 &&
787	          vr_render_answer(&agent_facts, display, sizeof(display), speech,
788	                           sizeof(speech)))
789	        {
790	          pthread_mutex_lock(&g_vr.ui_lock);
791	          snprintf(g_vr.ui.answer, sizeof(g_vr.ui.answer), "%s", display);
792	          pthread_mutex_unlock(&g_vr.ui_lock);
793	
794	          return vg_vs_agent_result(&g_vr.s, gen, true, speech, vr_now_ms());
795	        }
796	    }
797	
798	  /* Fallback: read once more via the tool and capture only this thread's
799	   * publication if the model tool did not supply matching facts. */
800	
801	  return vr_answer_from_tool(gen, tool, tool_json, config_version);
802	#endif
803	}
