805	#ifdef CONFIG_VG_VOICE_TTS_STREAM
806	
807	/* Streaming playback adapter: the cloud sink hands over 24 kHz mono
808	 * pieces; the incremental resampler turns them into the 16 kHz mono the
809	 * ring player takes. The shared bound includes the resampler's carry
810	 * samples and keeps the adapter off the large-stack failure path. */
811	
812	#define VR_TTS_FEED_SAMPLES VG_VC_RS_CHUNK_SAMPLES
813	
814	struct vr_tts_feed
815	{
816	  struct vg_pcm_rs24_16 rs;
817	  int16_t out[VR_TTS_FEED_SAMPLES];
818	  uint32_t mono_bytes;
819	};
820	
821	static int vr_tts_feed_push(void *ctx, const uint8_t *pcm24k, size_t bytes)
822	{
823	  struct vr_tts_feed *f = (struct vr_tts_feed *)ctx;
824	  long n = vg_pcm_rs24_16_feed(&f->rs, pcm24k, bytes, f->out,
825	                               VR_TTS_FEED_SAMPLES);
826	
827	  if (n < 0)
828	    {
829	      return -1;
830	    }
831	
832	  if (n > 0 && vg_tts_player_push((const uint8_t *)f->out,
833	                                  (size_t)n * 2u) != 0)
834	    {
835	      return -1;
836	    }
837	
838	  if (n > 0) f->mono_bytes += (uint32_t)n * 2u;
839	
840	  return 0;
841	}
