858	
859	static uint32_t vr_stage_tts(uint32_t gen)
860	{
861	  struct vg_vc_info info;
862	  enum vg_vc_result rc;
863	  vela_req_ctl_t ctl;
864	
865	  ctl.deadline_ms = g_vr.s.deadline_ms;
866	  ctl.cancel = &g_vr.cancel;
867	
868	  /* 重试播报也要暂停已恢复的后台请求，且沿用本次播报预算。 */
869	  while (vg_agent_round_voice_reserve() != 0)
870	    {
871	      if (g_vr.cancel) return 0;
872	      if ((int32_t)(g_vr.s.deadline_ms - vr_now_ms()) <= 0)
873	        return vg_vs_tts_result(&g_vr.s, gen, false, vr_now_ms());
874	      usleep(20000);
875	    }
876	
877	  vr_ui_set_status("合成语音");
878	  vr_ui_publish();
879	  vr_log_stage("tts_begin");
880	
881	#ifdef CONFIG_VG_VOICE_TTS_STREAM
882	  {
883	    uint32_t started_gen = gen;
884	
885	    int player_rc = vg_tts_player_start(vg_tts_player_prebuf_ms(),
886	                                       ctl.deadline_ms, &g_vr.cancel,
887	                                       vr_tts_started, &started_gen);
888	    if (player_rc == 0)
889	      {
890	        struct vr_tts_feed feed;
891	        struct vg_tts_player_stats pstats;
892	        uint32_t actions;
893	        uint32_t limit;
894	        int wr;
895	
896	        /* The span anchor the phase scripts read; the real first-sound
897	         * marker is the play_start stage the player thread logs. */
898	
899	        vr_log_stage("play_posted");
900	        vr_ui_set_status("缓冲语音");
901	        vr_ui_publish();
902	
903	        __atomic_fetch_add(&g_vr.tts_requests, 1, __ATOMIC_RELAXED);
904	        vg_pcm_rs24_16_init(&feed.rs);
905	        feed.mono_bytes = 0;
906	        rc = vg_voice_cloud_tts_stream(g_vr.s.answer, vr_tts_feed_push,
907	                                       &feed, &ctl, &info);
908	
909	        syslog(LOG_INFO,
910	               "[vgvoice] tts rc=%s status=%d pcm=%u resp=%u ms=%u "
911	               "stream=1 delivered_partial=%u\n",
912	               vg_vc_result_name(rc), info.status,
913	               (unsigned)info.audio_bytes, (unsigned)info.resp_bytes,
914	               (unsigned)info.elapsed_ms, (unsigned)info.partial);
915	        vr_log_stage("tts_end");
916	
917	        if (rc != VG_VC_OK)
918	          {
919	            /* Truncation, cancellation or transport failure: stop the
920	             * device right away and report a failed playback; whatever
921	             * was audible is already marked partial above. */
922	
923	            vg_tts_player_abort();
924	            (void)vg_tts_player_wait(3000, &pstats);
925	            syslog(LOG_INFO, "[vgvoice] tts_playback_failure started=%u "
926	                   "partial=%u failed=%u err=%d leaked=%u\n",
927	                   pstats.started, pstats.started, pstats.failed,
928	                   pstats.err, pstats.leaked_buffers);
929	
930	            if (g_vr.cancel)
931	              {
932	                return 0;
933	              }
934	
935	            return vg_vs_tts_result(&g_vr.s, gen, false, vr_now_ms());
936	          }
937	
938	        vg_tts_player_eof();
939	        actions = vg_vs_tts_result(&g_vr.s, gen, true, vr_now_ms());
940	
941	        /* Drain: everything pushed has to finish.  The bound is the
942	         * audio duration itself (32 mono bytes per ms) plus the same
943	         * slack the WAV wait uses; completion comes from the driver. */
944	
945	        limit = (feed.mono_bytes + 31u) / 32u + VR_PLAY_EXTRA_MS;
946	        wr = vg_tts_player_wait(limit, &pstats);
947	
948	        info.played_bytes = pstats.played_bytes;
949	        info.underruns = pstats.underruns;
950	        info.stall_ms = pstats.stall_ms;
951	
952	        syslog(LOG_INFO,
953	               "[vgvoice] tts_player played=%u pushed=%u underruns=%u "
954	               "stall_ms=%u restarts=%u complete=%u failed=%u err=%d "
955	               "leaked=%u ms=%u returned=%u ready_delay_ms=%u\n",
956	               (unsigned)pstats.played_bytes,
957	               (unsigned)pstats.pushed_bytes,
958	               (unsigned)pstats.underruns, (unsigned)pstats.stall_ms,
959	               (unsigned)pstats.restarts, pstats.complete ? 1u : 0u,
960	               pstats.failed ? 1u : 0u, pstats.err,
961	               (unsigned)pstats.leaked_buffers,
962	               (unsigned)(vr_now_ms() - g_vr.s.submit_ms),
963	               (unsigned)pstats.returned_bytes,
964	               (unsigned)pstats.start_delay_ms);
965	
966	        if (g_vr.cancel)
967	          {
968	            return 0;
969	          }
970	
971	        if (wr != 0 || !pstats.complete || pstats.failed)
972	          {
973	            actions |= vg_vs_tts_result(&g_vr.s, gen, false, vr_now_ms());
974	          }
975	        else
976	          {
977	            vr_log_stage("play_done");
978	            actions |= vg_vs_play_done(&g_vr.s, gen, vr_now_ms());
979	          }
980	
981	        return actions;
982	      }
983	    if (player_rc == -EBUSY)
984	      {
985	        /* 未回收的播放会话仍持有设备，不能让 WAV 回退抢占同一设备。 */
986	        return vg_vs_tts_result(&g_vr.s, gen, false, vr_now_ms());
987	      }
988	  }
989	
990	  /* The player could not open the device: this round falls back to the
991	   * WAV path below.  The decision happens before the request is sent,
992	   * so no synthesised audio is lost. */
993	#endif /* CONFIG_VG_VOICE_TTS_STREAM */
994	
995	  __atomic_fetch_add(&g_vr.tts_requests, 1, __ATOMIC_RELAXED);
996	  rc = vg_voice_cloud_tts(g_vr.s.answer, VG_VC_TTS_WAV_PATH, &ctl, &info);
997	
998	  syslog(LOG_INFO, "[vgvoice] tts rc=%s status=%d pcm=%u resp=%u ms=%u\n",
999	         vg_vc_result_name(rc), info.status, (unsigned)info.audio_bytes,
1000	         (unsigned)info.resp_bytes, (unsigned)info.elapsed_ms);
1001	  vr_log_stage("tts_end");
1002	
1003	  if (g_vr.cancel)
1004	    {
1005	      unlink(VG_VC_TTS_WAV_PATH);
1006	      return 0;
1007	    }
1008	
1009	  if (rc != VG_VC_OK)
1010	    {
1011	      /* The text is still valid; only playback failed. */
1012	
1013	      return vg_vs_tts_result(&g_vr.s, gen, false, vr_now_ms());
1014	    }
1015	
1016	  if (g_vr.cancel)
1017	    {
1018	      unlink(VG_VC_TTS_WAV_PATH);
1019	      return 0;
1020	    }
1021	
1022	  if ((int32_t)(g_vr.s.deadline_ms - vr_now_ms()) <= 0 ||
1023	      vg_voice_play_file(VG_VC_TTS_WAV_PATH) != 0)
1024	    {
1025	      unlink(VG_VC_TTS_WAV_PATH);
1026	      return vg_vs_tts_result(&g_vr.s, gen, false, vr_now_ms());
1027	    }
1028	
1029	  syslog(LOG_INFO, "[vgvoice] first_playable gen=%u elapsed_ms=%u\n",
1030	         (unsigned)gen, (unsigned)(vr_now_ms() - g_vr.s.submit_ms));
1031	  vr_log_stage("play_posted");
1032	  vr_ui_set_status("播报中");
1033	  vr_ui_publish();
1034	
1035	  {
1036	    uint32_t actions = vg_vs_tts_result(&g_vr.s, gen, true, vr_now_ms());
1037	    uint32_t limit = 60000;
1038	    struct stat st;
1039	
1040	    if (stat(VG_VC_TTS_WAV_PATH, &st) == 0 && st.st_size > 44)
1041	      {
1042	        /* 16 kHz stereo 16-bit: 64000 bytes per second. */
1043	
1044	        limit = (uint32_t)((st.st_size - 44) / 64) + VR_PLAY_EXTRA_MS;
1045	      }
1046	
1047	    bool idle = false;
1048	    uint32_t started = vr_now_ms();
1049	    while (!g_vr.cancel && vr_now_ms() - started < limit)
1050	      {
1051	        if ((idle = vr_wait_voice_idle(100))) break;
1052	      }
1053	    bool completed = idle;
1054	    if (!idle)
1055	      {
1056	        vg_voice_cancel();
1057	        idle = vr_wait_voice_idle(2000);
1058	      }
1059	    if (idle) unlink(VG_VC_TTS_WAV_PATH);
1060	    if (g_vr.cancel) return 0;
1061	
1062	    struct vg_voice_stats played;
1063	    vg_voice_get_stats(&played);
1064	    if (!completed || !idle || played.last_result != VG_VOICE_OK)
1065	      actions |= vg_vs_tts_result(&g_vr.s, gen, false, vr_now_ms());
1066	    else
1067	      {
1068	        /* The explicit playback-end marker the round metrics are read
1069	         * from; the settle below it is a fallback with coarser
1070	         * quantisation. */
1071	        vr_log_stage("play_done");
1072	        actions |= vg_vs_play_done(&g_vr.s, gen, vr_now_ms());
1073	      }
1074	    return actions;
1075	  }
1076	}
