1080	#ifdef CONFIG_AI_AGENT_VOICE_CONN_SLOT
1081	
1082	/* P2 phase 1: warm the ASR/TTS keep-alive connection while the user is
1083	 * still speaking.  The handshake is the deep part (mbedTLS peaks around
1084	 * 12 KB of stack; 24 KB leaves margin), so this gets its own thread —
1085	 * the round thread is busy owning the recorder.  Never joined: the
1086	 * transport's own deadline and cancel checks bound its life, and the
1087	 * single-flight guard keeps one thread at a time.  A cancel observed
1088	 * mid-handshake destroys the half-built connection; one that finished
1089	 * before the cancel stays published and only helps the next round. */
1090	
1091	static volatile int g_preconnect_running;
1092	
1093	static void *vr_preconnect_thread(void *arg)
1094	{
1095	  vela_req_ctl_t ctl;
1096	  agent_llm_timing_t t;
1097	  uint32_t t0;
1098	
1099	  (void)arg;
1100	  ctl.deadline_ms = vr_now_ms() + 8000u;
1101	  ctl.cancel = &g_vr.cancel;
1102	
1103	  agent_timing_reset(&t);
1104	  t0 = vr_now_ms();
1105	  int rc = agent_http_voice_preconnect(&ctl, &t);
1106	
1107	  syslog(LOG_INFO, "[vgvoice] voice_preconnect rc=%d dns=%d tls=%d ms=%u\n",
1108	         rc, (int)t.dns_tcp_ms, (int)t.tls_ms,
1109	         (unsigned)(vr_now_ms() - t0));
1110	
1111	  g_preconnect_running = 0;
1112	  return NULL;
1113	}
1114	
1115	static void vr_preconnect_start(void)
1116	{
1117	  pthread_attr_t attr;
1118	  pthread_t tid;
1119	  int expected = 0;
1120	
1121	  if (!__atomic_compare_exchange_n(&g_preconnect_running, &expected, 1,
1122	                                   false, __ATOMIC_ACQ_REL,
1123	                                   __ATOMIC_RELAXED))
1124	    {
1125	      return;   /* one in flight */
1126	    }
1127	
1128	  pthread_attr_init(&attr);
1129	  pthread_attr_setstacksize(&attr, 24576);
1130	
1131	  if (pthread_create(&tid, &attr, vr_preconnect_thread, NULL) != 0)
1132	    {
1133	      g_preconnect_running = 0;
1134	      return;
1135	    }
1136	
1137	  pthread_detach(tid);
1138	}
1139	
1140	#endif /* CONFIG_AI_AGENT_VOICE_CONN_SLOT */
1141	
1142	static void vr_run_actions(uint32_t actions)
1143	{
1144	  int guard;
1145	
1146	  for (guard = 0; guard < 8 && actions != 0; guard++)
1147	    {
1148	      uint32_t next = 0;
1149	
1150	      if ((actions & VG_VS_ACT_STOP_PLAYBACK) != 0)
1151	        {
1152	          (void)vg_voice_cancel();
1153	          if (vr_wait_voice_idle(2000))
1154	            {
1155	              next |= vg_vs_audio_stopped(&g_vr.s, vr_now_ms());
1156	            }
1157	          else
1158	            {
1159	              vr_ui_error("播放未能停止");
1160	              next |= vg_vs_end(&g_vr.s, vr_now_ms());
1161	            }
1162	        }
1163	
1164	      if ((actions & VG_VS_ACT_CANCEL_AGENT) != 0)
1165	        {
1166	          /* A new press replaced the question.  Release the agent slot so
1167	           * the replacement can be submitted; the old reply is dropped by
1168	           * its serial. */
1169	
1170	          vg_agent_round_abandon_owned(VG_AGENT_ROUND_OWNER_VOICE);
1171	        }
1172	
1173	      if ((actions & VG_VS_ACT_STOP_RECORD) != 0)
1174	        {
1175	          if (g_vr.record_generation != 0)
1176	            {
1177	              (void)vg_voice_finish_owned_silent(g_vr.record_generation);
1178	              g_vr.record_generation = 0;
1179	            }
1180	          /* 正常松手和到达录音上限会同时请求 START_ASR，必须保留 PCM
1181	           * 和句柄供识别取用。取消或录音过短没有后续取用，才清理。 */
1182	          if ((actions & VG_VS_ACT_START_ASR) == 0 &&
1183	              g_vr.clip_generation != 0)
1184	            {
1185	              (void)vg_voice_finish_owned(g_vr.clip_generation, true);
1186	              g_vr.clip_generation = 0;
1187	            }
1188	        }
1189	
1190	      if ((actions & VG_VS_ACT_START_RECORD) != 0)
1191	        {
1192	          uint32_t gen = 0;
1193	          int rc;
1194	
1195	          /* A previous round may still be writing its WAV.  Starting a
1196	           * recording on top of that produced a phantom capture and then
1197	           * "录音未正常结束" at the next stage; wait for the worker to settle
1198	           * first and fail with a clear reason if it does not. */
1199	
1200	          if (!vg_voice_wait_idle(2000))
1201	            {
1202	              vr_ui_error("录音设备忙，请稍后再试");
1203	              next |= vg_vs_end(&g_vr.s, vr_now_ms());
1204	            }
1205	          else if ((rc = vg_voice_record_begin_owned(&gen)) < 0)
1206	            {
1207	              vr_ui_error("录音启动失败");
1208	              next |= vg_vs_end(&g_vr.s, vr_now_ms());
1209	            }
1210	          else
1211	            {
1212	              g_vr.cancel = g_vr.end_pending || g_vr.press_pending || g_vr.quit;
1213	              g_vr.record_generation = gen;
1214	              g_vr.clip_generation = gen;
1215	              vr_ui_clear_error();
1216	              vr_ui_set_status("录音中");
1217	
1218	#ifdef CONFIG_AI_AGENT_VOICE_CONN_SLOT
1219	              /* The round thread will be busy with the recorder until
1220	               * release; warm the connection it needs right after. */
1221	
1222	              vr_preconnect_start();
1223	#endif
1224	
1225	              pthread_mutex_lock(&g_vr.ui_lock);
1226	              g_vr.ui.answer[0] = '\0';
1227	              g_vr.ui.error[0] = '\0';
1228	              pthread_mutex_unlock(&g_vr.ui_lock);
1229	            }
1230	        }
1231	
1232	      if ((actions & VG_VS_ACT_START_ASR) != 0)
1233	        {
1234	          uint32_t gen = g_vr.s.generation;
1235	          char text[VG_VS_TEXT_MAX];
1236	
1237	          text[0] = '\0';
1238	
1239	          if (g_vr.cancel) return;
1240	
1241	          /* The recorder stops the PDM stream, drains and writes the WAV;
1242	           * 2 s was tight enough to lose a round right after playback. */
1243	
1244	          vr_log_stage("asr_wait_recorder");
1245	          if (!vr_wait_voice_idle(5000))
1246	            {
1247	              vr_ui_error("录音未正常结束");
1248	              next |= vg_vs_asr_result(&g_vr.s, gen, false, NULL,
1249	                                       vr_now_ms());
1250	            }
1251	          else if (!vr_stage_asr(text, sizeof(text)))
1252	            {
1253	              if (!g_vr.cancel)
1254	                {
1255	                  next |= vg_vs_asr_result(&g_vr.s, gen, false, NULL,
1256	                                           vr_now_ms());
1257	                }
1258	            }
1259	          else
1260	            {
1261	              next |= vg_vs_asr_result(&g_vr.s, gen, true, text,
1262	                                       vr_now_ms());
1263	            }
1264	        }
1265	
1266	      if ((actions & VG_VS_ACT_QUEUE_AGENT) != 0)
1267	        {
1268	          if (g_vr.cancel) return;
1269	          next |= vr_stage_agent(g_vr.s.text, g_vr.s.generation);
1270	        }
1271	
1272	      if ((actions & VG_VS_ACT_START_TTS) != 0)
1273	        {
1274	          if (g_vr.cancel) return;
1275	          next |= vr_stage_tts(g_vr.s.generation);
1276	        }
1277	
1278	      if ((actions & VG_VS_ACT_SHOW_RESULT) != 0)
1279	        {
1280	          vr_show_result();
1281	        }
1282	
1283	      if ((actions & VG_VS_ACT_SHOW_ERROR) != 0)
1284	        {
1285	          vr_show_error();
1286	        }
1287	
1288	      if ((actions & VG_VS_ACT_HIDE_OVERLAY) != 0)
1289	        {
1290	          vg_agent_round_voice_release();
1291	          pthread_mutex_lock(&g_vr.ui_lock);
1292	          g_vr.ui.visible = false;
1293	          g_vr.ui.status[0] = '\0';
1294	          g_vr.ui.error[0] = '\0';
1295	          g_vr.ui.answer[0] = '\0';
1296	          g_vr.ui.question[0] = '\0';
1297	          pthread_mutex_unlock(&g_vr.ui_lock);
1298	        }
1299	
1300	      if ((actions & VG_VS_ACT_RELEASE_AUDIO) != 0)
1301	        {
1302	          if (g_vr.clip_generation)
1303	            (void)vg_voice_finish_owned(g_vr.clip_generation, true);
1304	          vg_voice_cloud_cleanup();
1305	          if (vg_voice_wait_idle(0)) unlink(VG_VC_TTS_WAV_PATH);
1306	        }
1307	
1308	      actions = next;
1309	    }
1310	
1311	  vr_ui_publish();
1312	}
