1314	/* ── worker ─────────────────────────────────────────────────────── */
1315	
1316	static void *vr_thread(void *arg)
1317	{
1318	  (void)arg;
1319	
1320	  while (!g_vr.quit)
1321	    {
1322	      struct timespec ts;
1323	      uint32_t actions;
1324	      uint32_t now;
1325	
1326	      clock_gettime(CLOCK_REALTIME, &ts);
1327	      ts.tv_nsec += VR_TICK_MS * 1000000L;
1328	      if (ts.tv_nsec >= 1000000000L)
1329	        {
1330	          ts.tv_sec += 1;
1331	          ts.tv_nsec -= 1000000000L;
1332	        }
1333	
1334	      (void)sem_timedwait(&g_vr.wake, &ts);
1335	
1336	      now = vr_now_ms();
1337	
1338	      if (g_vr.press_pending)
1339	        {
1340	          g_vr.press_pending = false;
1341	          actions = vg_vs_press(&g_vr.s, now);
1342	          vr_run_actions(actions);
1343	          now = vr_now_ms();
1344	        }
1345	
1346	      if (g_vr.submit_pending)
1347	        {
1348	          g_vr.submit_pending = false;
1349	          actions = vg_vs_release(&g_vr.s, now);
1350	          vr_run_actions(actions);
1351	          now = vr_now_ms();
1352	        }
1353	
1354	      /* Overlay commands arrive from the LVGL thread.  They only set a flag
1355	       * here: the worker runs the pipeline, so a retry that needs 30 s of
1356	       * network never blocks the UI. */
1357	
1358	      if (g_vr.end_pending)
1359	        {
1360	          g_vr.end_pending = false;
1361	          vr_run_actions(vg_vs_end(&g_vr.s, now));
1362	          now = vr_now_ms();
1363	        }
1364	
1365	      if (g_vr.retry_pending)
1366	        {
1367	          g_vr.retry_pending = false;
1368	          g_vr.cancel = g_vr.end_pending || g_vr.press_pending || g_vr.quit;
1369	          vr_run_actions(vg_vs_retry_tts(&g_vr.s, now));
1370	          now = vr_now_ms();
1371	        }
1372	
1373	      /* The session belongs to this thread.  The overlay's hold and mute
1374	       * switches arrive as pending values so no other thread mutates it. */
1375	
1376	      if (g_vr.hold_pending)
1377	        {
1378	          g_vr.hold_pending = false;
1379	          g_vr.hold = g_vr.hold_value;
1380	          vg_vs_result_hold(&g_vr.s, g_vr.hold, now);
1381	        }
1382	
1383	      if (g_vr.mute_pending)
1384	        {
1385	          g_vr.mute_pending = false;
1386	          g_vr.muted = g_vr.mute_value;
1387	          vg_vs_set_muted(&g_vr.s, g_vr.mute_value);
1388	        }
1389	
1390	#ifdef CONFIG_VG_BUS_DISCOVER
1391	      /* A committed point-table change bumps the live generation.  Feed it to
1392	       * the session so an in-flight question ends instead of answering from a
1393	       * table that may no longer contain the points it names. */
1394	
1395	      vg_vs_set_config_version(&g_vr.s, vg_live_points_gen());
1396	#endif
1397	
1398	      actions = vg_vs_tick(&g_vr.s, now);
1399	      vr_run_actions(actions);
1400	      vr_log_cancel_settled();
1401	
1402	      if (g_vr.s.state == VG_VS_RESULT && !g_vr.hold)
1403	        {
1404	          /* Nothing to do: the session owns the 15 s timer. */
1405	        }
1406	    }
1407	
1408	  return NULL;
1409	}
