1413	int vg_voice_round_start(void)
1414	{
1415	  int ret;
1416	
1417	  pthread_mutex_lock(&g_start_lock);
1418	
1419	  if (g_vr.started)
1420	    {
1421	      pthread_mutex_unlock(&g_start_lock);
1422	      return 0;
1423	    }
1424	
1425	  memset(&g_vr, 0, sizeof(g_vr));
1426	  pthread_mutex_init(&g_vr.ui_lock, NULL);
1427	  sem_init(&g_vr.wake, 0, 0);
1428	  vg_vs_init(&g_vr.s, vr_now_ms());
1429	  g_vr.s.muted = false;
1430	
1431	  ret = vg_voice_init();
1432	  if (ret < 0)
1433	    {
1434	      pthread_mutex_unlock(&g_start_lock);
1435	      return ret;
1436	    }
1437	
1438	  {
1439	    pthread_attr_t attr;
1440	
1441	    pthread_attr_init(&attr);
1442	    pthread_attr_setstacksize(&attr, VR_STACK_SIZE);
1443	    ret = pthread_create(&g_vr.thread, &attr, vr_thread, NULL);
1444	    pthread_attr_destroy(&attr);
1445	  }
1446	
1447	  if (ret != 0)
1448	    {
1449	      pthread_mutex_unlock(&g_start_lock);
1450	      return -ret;
1451	    }
1452	
1453	  /* The button layer starts after the worker exists, so an early press is
1454	   * never dropped on the floor. */
1455	
1456	  ret = vg_ptt_start(NULL, vr_button, NULL);
1457	  if (ret < 0)
1458	    {
1459	      g_vr.quit = true;
1460	      sem_post(&g_vr.wake);
1461	      pthread_join(g_vr.thread, NULL);
1462	      pthread_mutex_unlock(&g_start_lock);
1463	      return ret;
1464	    }
1465	
1466	  g_vr.started = true;
1467	  g_round_ready = true;
1468	  pthread_mutex_unlock(&g_start_lock);
1469	  return 0;
1470	}
