1492	int vg_voice_round_stack(size_t *size, size_t *used, size_t *headroom)
1493	{
1494	#ifdef CONFIG_STACK_COLORATION
1495	  struct tcb_s *tcb;
1496	  size_t total;
1497	  size_t highwater;
1498	
1499	  pthread_mutex_lock(&g_start_lock);
1500	  if (!g_vr.started)
1501	    {
1502	      pthread_mutex_unlock(&g_start_lock);
1503	      return -ENOENT;
1504	    }
1505	
1506	  tcb = nxsched_get_tcb(pthread_gettid_np(g_vr.thread));
1507	  if (tcb == NULL)
1508	    {
1509	      pthread_mutex_unlock(&g_start_lock);
1510	      return -ESRCH;
1511	    }
1512	
1513	  /* NuttX colors the stack before starting the thread.  Its adjusted base
1514	   * excludes TLS and alignment, so headroom counts usable stack only.
1515	   * A TCB reference plus the lifecycle lock keeps the stack alive here. */
1516	
1517	  total = tcb->adj_stack_size;
1518	  highwater = up_check_tcbstack(tcb, total);
1519	  nxsched_put_tcb(tcb);
1520	  pthread_mutex_unlock(&g_start_lock);
1521	
1522	  if (size != NULL)
1523	    {
1524	      *size = total;
1525	    }
1526	
1527	  if (used != NULL)
1528	    {
1529	      *used = highwater;
1530	    }
1531	
1532	  if (headroom != NULL)
1533	    {
1534	      *headroom = total - highwater;
1535	    }
1536	
1537	  return 0;
1538	#else
1539	  return -ENOSYS;
1540	#endif
1541	}
