53	
54	/* The agent loop hands a tool a 4 KB buffer on the HMI build
55	 * (TOOL_OUTPUT_SIZE).  Stay well under it so the model never receives a
56	 * half-line: the list form is the only one that can grow. */
57	#define VG_AGENT_TOOL_OUT_MAX 2048
58	
59	/* Argument caps.  tool_guard.c enforces a 32 KB input limit and a call-rate
60	 * window but does not validate a tool's JSON Schema, so the bounds a schema
61	 * advertises have to be enforced here too. */
62	#define VG_AGENT_TOOL_QUERY_MAX 48
63	
64	#ifndef CONFIG_VG_DISCOVER_POINTS_PATH
65	#  define CONFIG_VG_DISCOVER_POINTS_PATH "/data/velaguard/config/points.json"
66	#endif
