81	
82	/* ── table + snapshot join ───────────────────────────────────────── */
83	
84	/* Build the agent-facing view of the confirmed table.  Returns 0 when values
85	 * are available, or a vg_agent_query_rc reason otherwise.  Values come from
86	 * the live snapshot, which is written with tmp+rename so a reader never sees
87	 * a torn file. */
88	
89	static enum vg_agent_query_rc collect_points(struct vg_agent_point *out,
90	                                             int *n_out)
91	{
92	  struct vg_discover_summary table;
93	  struct vg_live_snapshot snap;
94	  bool have_snap = false;
95	  enum vg_agent_query_rc rc = VG_AGENT_QUERY_OK;
96	  uint32_t age = 0;
97	  int i;
98	  int rc_read;
99	
100	  if (out == NULL || n_out == NULL)
101	    {
102	      return VG_AGENT_QUERY_ARG;
103	    }
104	
105	  *n_out = 0;
106	#ifdef CONFIG_VG_HMI_DISCOVER
107	  rc_read = vg_live_points_view(&table, &snap, NULL);
108	  if (rc_read <= 0) return VG_AGENT_QUERY_NO_TABLE;
109	  if (snap.tick_ms != 0)
110	    {
111	      uint32_t now = vg_live_now_ms();
112	      if ((int32_t)(now - snap.tick_ms) >= 0)
113	        {
114	          have_snap = true;
115	          age = now - snap.tick_ms;
116	        }
117	    }
118	#else
119	  rc_read = vg_point_table_read(&table, CONFIG_VG_DISCOVER_POINTS_PATH);
120	
121	  if (rc_read == -ENOENT)
122	    {
123	      /* An absent table is empty only while the store itself is reachable.
124	       * When /data is gone the honest answer is "cannot read", not "no
125	       * points configured": the two look identical otherwise, and the NSH
126	       * tools separate them the same way (vgpoint.c cmd_get). */
127	      if (vg_point_store_root_ok(CONFIG_VG_STORE_ROOT) == 0)
128	        {
129	          memset(&table, 0, sizeof(table));
130	          rc_read = 0;
131	        }
132	    }
133	
134	  if (rc_read != 0 || table.n_points <= 0)
135	    {
136	      return VG_AGENT_QUERY_NO_TABLE;
137	    }
138	
139	  if (vg_live_snapshot_read(CONFIG_VG_LIVE_VALUES_PATH, &snap) == 0 &&
140	      snap.tick_ms != 0)
141	    {
142	      /* The snapshot file survives a reboot, but its tick is a monotonic
143	       * uptime from the boot that wrote it.  A tick ahead of the current
144	       * uptime therefore means "written by an earlier boot", and ageing it
145	       * would wrap to about 49 days.  Report no sample instead of a number
146	       * that looks like a measurement. */
147	
148	      uint32_t now = vg_live_now_ms();
149	
150	      if ((int32_t)(now - snap.tick_ms) >= 0)
151	        {
152	          have_snap = true;
153	          age = now - snap.tick_ms;
154	        }
155	    }
156	
157	#endif
158	
159	  for (i = 0; i < table.n_points && i < VG_AGENT_QUERY_MAX; i++)
160	    {
161	      const struct vg_point_entry *e = &table.points[i];
162	      struct vg_agent_point *p = &out[i];
163	      int idx;
164	
165	      memset(p, 0, sizeof(*p));
166	      snprintf(p->id, sizeof(p->id), "%s", e->id);
167	      snprintf(p->name, sizeof(p->name), "%s",
168	               e->name[0] ? e->name : e->id);
169	      snprintf(p->unit, sizeof(p->unit), "%s", e->unit);
170	      snprintf(p->cmp, sizeof(p->cmp), "%s", e->cmp);
171	      p->has_warn = e->has_warn != 0;
172	      p->warn = e->warn;
173	      p->has_crit = e->has_crit != 0;
174	      p->crit = e->crit;
175	
176	      if (!have_snap)
177	        {
178	          continue;
179	        }
180	
181	      idx = vg_live_snapshot_find_id(&snap, e->id);
182	      if (idx < 0)
183	        {
184	          continue;
185	        }
186	
187	      p->has_sample = true;
188	      p->ok = snap.samples[idx].ok != 0;
189	      p->value = snap.samples[idx].value;
190	      p->age_ms = age;
191	    }
192	
193	  if (!have_snap)
194	    {
195	      /* The table is known but nothing has been sampled yet.  Report the
196	       * thresholds without inventing values. */
197	      rc = VG_AGENT_QUERY_NO_SAMPLE;
198	    }
199	
200	  *n_out = (table.n_points < VG_AGENT_QUERY_MAX)
201	               ? table.n_points
202	               : VG_AGENT_QUERY_MAX;
203	  return rc;
204	}
205	
206	static int tool_point_read(const char *query, char *out, size_t cap)
207	{
208	  struct vg_agent_point points[VG_AGENT_QUERY_MAX];
209	  struct vg_agent_query_result res;
210	  enum vg_agent_query_rc collect_rc;
211	  enum vg_agent_query_rc rc;
212	  int n = 0;
213	
214	  collect_rc = collect_points(points, &n);
215	
216	  if (collect_rc == VG_AGENT_QUERY_NO_TABLE)
217	    {
218	      snprintf(out, cap,
219	               "vgquery: reason=no_table msg=已确认点表不可读或尚未导入\n");
220	      return OK;
221	    }
222	
223	  if (n <= 0)
224	    {
225	      snprintf(out, cap, "vgquery: reason=no_table msg=已确认点表为空\n");
226	      return OK;
227	    }
228	
229	  rc = vg_agent_query_match(points, n, query, &res);
230	
231	  switch (rc)
232	    {
233	      case VG_AGENT_QUERY_OK:
234	        {
235	          const struct vg_agent_point *p = &points[res.index];
236	
237	          vg_agent_query_format_point(out, cap, p,
238	                                      vg_agent_query_is_stale(p));
239	
240	          /* Publish the same reading the model was given.  The overlay and
241	           * the speech renderer read this snapshot, so they cannot show a
242	           * different value from the one the tool returned. */
243	
244	          vg_voice_facts_publish_point(p->id, p->name, p->unit, p->ok,
245	                                       p->has_sample && p->ok, p->value,
246	                                       p->age_ms, p->has_warn, p->warn,
247	                                       p->has_crit, p->crit, p->cmp);
248	        }
249	        break;
250	
251	      case VG_AGENT_QUERY_AMBIG:
252	        vg_agent_query_format_candidates(out, cap, points, n, &res);
253	        break;
254	
255	      case VG_AGENT_QUERY_NOT_FOUND:
256	        vg_agent_query_format_list(out, cap, points, n);
257	        snprintf(out + strlen(out), cap - strlen(out),
258	                 "vgquery: reason=not_found query=%s\n",
259	                 (query != NULL) ? query : "");
260	        break;
261	
262	      case VG_AGENT_QUERY_LIST:
263	      default:
264	        vg_agent_query_format_list(out, cap, points, n);
265	        break;
266	    }
267	
268	  /* Reaching here means the question was answered, including "no sample
269	   * yet": that is a real answer, and the text says where the data is
270	   * missing.  Only an unreadable table takes the early return above. */
271	  return OK;
272	}
