274	/* Public wrapper for the voice path: it resolves a spoken point name before
275	 * submitting a question, so an ambiguous name never reaches the model. */
276	
277	int vg_agent_tools_collect(struct vg_agent_point *out, int max, int *n_out)
278	{
279	  struct vg_agent_point all[VG_AGENT_QUERY_MAX];
280	  int n = 0;
281	  int i;
282	  enum vg_agent_query_rc rc = collect_points(all, &n);
283	
284	  if (out == NULL || n_out == NULL || max <= 0)
285	    {
286	      return VG_AGENT_QUERY_ARG;
287	    }
288	
289	  if (n > max)
290	    {
291	      n = max;
292	    }
293	
294	  for (i = 0; i < n; i++)
295	    {
296	      out[i] = all[i];
297	    }
298	
299	  *n_out = n;
300	  return (int)rc;
301	}
