325	static const char *vg_rank_name(uint8_t rank)
326	{
327	  switch (rank)
328	    {
329	      case 0: return "crit";
330	      case 1: return "warn";
331	      case 2: return "offline";
332	      default: return "stale";
333	    }
334	}
335	
336	static int tool_anomaly_read(char *out, size_t cap)
337	{
338	  struct vg_runtime_anomaly items[VG_RUNTIME_MAX_POINTS];
339	  int total = 0;
340	  int n;
341	  int listed;
342	  int i;
343	  size_t off = 0;
344	  uint32_t oldest = 0;
345	
346	  n = vg_runtime_anomalies(items, VG_RUNTIME_MAX_POINTS, &total,
347	                           VG_AGENT_QUERY_STALE_MS);
348	  if (n < 0)
349	    {
350	      snprintf(out, cap, "vganomaly: reason=bad_state msg=运行层不可用\n");
351	      return OK;
352	    }
353	
354	  for (i = 0; i < n; i++)
355	    {
356	      if (items[i].age_ms > oldest)
357	        {
358	          oldest = items[i].age_ms;
359	        }
360	    }
361	
362	  vg_voice_facts_publish_anomalies(items, n, total,
363	                                   vg_runtime_points_seen(), oldest);
364	
365	  listed = n;
366	
367	  /* Each line is about 90 bytes; 12 lines plus the header stay inside the
368	   * 2 KB tool budget.  The header carries the real total either way. */
369	
370	  if (listed > 12)
371	    {
372	      listed = 12;
373	    }
374	
375	  off += (size_t)snprintf(out + off, cap - off,
376	                          "vganomaly: total=%d shown=%d seen=%d boot=%08x\n",
377	                          total, listed, vg_runtime_points_seen(),
378	                          (unsigned)vg_runtime_boot_id());
379	
380	  /* No point noted yet means the first acquisition cycle has not finished.
381	   * Saying so prevents an empty list from reading as a healthy site. */
382	
383	  if (vg_runtime_points_seen() == 0)
384	    {
385	      off += (size_t)snprintf(out + off, cap - off,
386	                              "note=first_cycle_pending\n");
387	    }
388	
389	  for (i = 0; i < listed && off < cap; i++)
390	    {
391	      const struct vg_runtime_anomaly *a = &items[i];
392	      char flags[32];
393	      char value[24];
394	      size_t fl = 0;
395	
396	      /* The separator goes before every flag after the first, because the
397	       * first flag is not always threshold.  A leading comma made the
398	       * offline-only line read "flags=,offline", which a model can echo. */
399	
400	      flags[0] = '\0';
401	
402	      if ((a->flags & VG_RUNTIME_ANOMALY_F_THRESHOLD) != 0)
403	        {
404	          fl += (size_t)snprintf(flags + fl, sizeof(flags) - fl, "%s",
405	                                 "threshold");
406	        }
407	
408	      if ((a->flags & VG_RUNTIME_ANOMALY_F_OFFLINE) != 0)
409	        {
410	          fl += (size_t)snprintf(flags + fl, sizeof(flags) - fl, "%soffline",
411	                                 (fl > 0) ? "," : "");
412	        }
413	
414	      if ((a->flags & VG_RUNTIME_ANOMALY_F_STALE) != 0)
415	        {
416	          fl += (size_t)snprintf(flags + fl, sizeof(flags) - fl, "%sstale",
417	                                 (fl > 0) ? "," : "");
418	        }
419	
420	      /* A point that never sampled has no reading.  Printing 0.0 would let
421	       * the answer claim a value the bus never returned. */
422	
423	      if (a->has_value)
424	        {
425	          snprintf(value, sizeof(value), "%.1f", a->value);
426	        }
427	      else
428	        {
429	          snprintf(value, sizeof(value), "-");
430	        }
431	
432	      off += (size_t)snprintf(out + off, cap - off,
433	                              "- id=%s rank=%s flags=%s value=%s "
434	                              "threshold=%.1f age_ms=%u since_ms=%u\n",
435	                              a->id, vg_rank_name(a->rank), flags, value,
436	                              a->threshold, (unsigned)a->age_ms,
437	                              (unsigned)a->since_ms);
438	    }
439	
440	  if (listed < n && off < cap)
441	    {
442	      snprintf(out + off, cap - off, "- omitted=%d\n", n - listed);
443	    }
444	
445	  return OK;
446	}
