448	static int tool_alarm_recovery(const char *input_json, char *out, size_t cap)
449	{
450	  struct vg_runtime_recovery rec;
451	  cJSON *root;
452	  cJSON *item;
453	  char id[VG_AGENT_TOOL_QUERY_MAX];
454	  enum vg_runtime_kind kind = VG_RUNTIME_KIND_THRESHOLD;
455	  int rc;
456	
457	  id[0] = '\0';
458	
459	  if (input_json == NULL || input_json[0] == '\0')
460	    {
461	      snprintf(out, cap, "vgrecovery: reason=bad_arg msg=缺少 point_id\n");
462	      return OK;
463	    }
464	
465	  root = cJSON_Parse(input_json);
466	  if (root == NULL)
467	    {
468	      snprintf(out, cap, "vgrecovery: reason=bad_arg msg=参数不是合法 JSON\n");
469	      return OK;
470	    }
471	
472	  item = cJSON_GetObjectItem(root, "point_id");
473	  if (item == NULL || !cJSON_IsString(item) || item->valuestring == NULL ||
474	      item->valuestring[0] == '\0')
475	    {
476	      cJSON_Delete(root);
477	      snprintf(out, cap, "vgrecovery: reason=bad_arg msg=缺少 point_id\n");
478	      return OK;
479	    }
480	
481	  if (strlen(item->valuestring) >= sizeof(id))
482	    {
483	      cJSON_Delete(root);
484	      snprintf(out, cap, "vgrecovery: reason=bad_arg msg=point_id 过长\n");
485	      return OK;
486	    }
487	
488	  snprintf(id, sizeof(id), "%s", item->valuestring);
489	
490	  item = cJSON_GetObjectItem(root, "kind");
491	  if (item != NULL && cJSON_IsString(item) && item->valuestring != NULL)
492	    {
493	      if (strcmp(item->valuestring, "offline") == 0)
494	        {
495	          kind = VG_RUNTIME_KIND_OFFLINE;
496	        }
497	      else if (strcmp(item->valuestring, "threshold") != 0)
498	        {
499	          cJSON_Delete(root);
500	          snprintf(out, cap,
501	                   "vgrecovery: reason=bad_arg msg=kind 只能是 threshold 或 "
502	                   "offline\n");
503	          return OK;
504	        }
505	    }
506	
507	  cJSON_Delete(root);
508	
509	  memset(&rec, 0, sizeof(rec));
510	  rc = vg_runtime_recovery(id, kind, &rec);
511	
512	  if (rc < 0)
513	    {
514	      snprintf(out, cap,
515	               "vgrecovery: id=%s kind=%s state=unknown history_complete=false\n",
516	               id, kind == VG_RUNTIME_KIND_OFFLINE ? "offline" : "threshold");
517	      return OK;
518	    }
519	
520	  vg_voice_facts_publish_recovery(&rec, 0);
521	
522	  snprintf(out, cap,
523	           "vgrecovery: id=%s kind=%s state=%s history_complete=%s "
524	           "duration_ms=%u episode=%u boot=%08x\n",
525	           rec.id, kind == VG_RUNTIME_KIND_OFFLINE ? "offline" : "threshold",
526	           rec.state == VG_RUNTIME_RECOVERY_ACTIVE        ? "active"
527	           : rec.state == VG_RUNTIME_RECOVERY_RECOVERED  ? "recovered"
528	           : rec.state == VG_RUNTIME_RECOVERY_RECOVERED_PARTIAL
529	               ? "recovered_partial"
530	               : "unknown",
531	           rec.history_complete ? "true" : "false", (unsigned)rec.duration_ms,
532	           (unsigned)rec.episode, (unsigned)vg_runtime_boot_id());
533	
534	  return OK;
535	}
