591	/* Assemble only the tools whose data source this build actually has. */
592	
593	static size_t app_str(char *buf, size_t cap, size_t off, const char *s)
594	{
595	  size_t n;
596	
597	  if (buf == NULL || cap == 0 || s == NULL || off >= cap - 1)
598	    {
599	      return off;
600	    }
601	
602	  n = strlen(s);
603	  if (n > cap - 1 - off)
604	    {
605	      n = cap - 1 - off;
606	    }
607	
608	  memcpy(buf + off, s, n);
609	  buf[off + n] = '\0';
610	  return off + n;
611	}
612	
613	static char *vg_tools_get_json(void)
614	{
615	  char buf[2048];
616	  size_t off = 0;
617	
618	  buf[0] = '\0';
619	  off = app_str(buf, sizeof(buf), off, "[");
620	
621	  /* The comma is chosen at compile time because the set of tools is fixed
622	   * then; a runtime "is this the first entry" flag would be dead code in
623	   * every single-tool build. */
624	
625	#ifdef VG_AGENT_TOOLS_HAVE_POINTS
626	  off = app_str(buf, sizeof(buf), off, VG_TOOL_POINT_JSON);
627	#endif
628	
629	#ifdef VG_AGENT_TOOLS_HAVE_REPORT
630	#  ifdef VG_AGENT_TOOLS_HAVE_POINTS
631	  off = app_str(buf, sizeof(buf), off, ",");
632	#  endif
633	
634	  off = app_str(buf, sizeof(buf), off, VG_TOOL_REPORT_JSON);
635	#endif
636	
637	#ifdef VG_AGENT_TOOLS_HAVE_REPORT
638	#  ifdef VG_AGENT_TOOLS_HAVE_POINTS
639	  off = app_str(buf, sizeof(buf), off, ",");
640	#  endif
641	
642	  off = app_str(buf, sizeof(buf), off, VG_TOOL_ANOMALY_JSON);
643	  off = app_str(buf, sizeof(buf), off, ",");
644	  off = app_str(buf, sizeof(buf), off, VG_TOOL_RECOVERY_JSON);
645	#endif
646	
647	  (void)app_str(buf, sizeof(buf), off, "]");
648	
649	  return strdup(buf);
650	}
