652	/* Extract the optional query string and bound it.  Returns 0 on success and
653	 * leaves *query NULL when the caller omitted it.  Only vg_point_read takes an
654	 * argument, so this lives inside that tool's build guard. */
655	
656	#ifdef VG_AGENT_TOOLS_HAVE_POINTS
657	static int parse_query(const char *input_json, char *buf, size_t cap,
658	                       const char **query)
659	{
660	  cJSON *root;
661	  cJSON *item;
662	  const char *s;
663	  size_t len;
664	
665	  *query = NULL;
666	
667	  if (input_json == NULL || input_json[0] == '\0')
668	    {
669	      return 0;
670	    }
671	
672	  root = cJSON_Parse(input_json);
673	  if (root == NULL)
674	    {
675	      return -EINVAL;
676	    }
677	
678	  item = cJSON_GetObjectItem(root, "query");
679	  if (item == NULL || cJSON_IsNull(item))
680	    {
681	      cJSON_Delete(root);
682	      return 0;
683	    }
684	
685	  if (!cJSON_IsString(item))
686	    {
687	      cJSON_Delete(root);
688	      return -EINVAL;
689	    }
690	
691	  s = item->valuestring;
692	  len = strlen(s);
693	
694	  if (len >= cap)
695	    {
696	      /* Reject rather than truncate: a cut point name could match a
697	       * different point and answer the wrong question. */
698	      cJSON_Delete(root);
699	      return -E2BIG;
700	    }
701	
702	  memcpy(buf, s, len + 1);
703	  *query = buf;
704	  cJSON_Delete(root);
705	  return 0;
706	}
707	#endif /* VG_AGENT_TOOLS_HAVE_POINTS */
708	
709	/* ── call rate ───────────────────────────────────────────────────────
710	 *
711	 * tool_guard.c rate-limits run_shell / write_file / edit_file only, so a
712	 * read-only tool has no ceiling there.  AGENTS.md requires the limit to live
713	 * in C rather than the prompt, and an unthrottled read is still an eMMC read
714	 * on every iteration, so cap it here.  The ReAct loop already bounds a round
715	 * (10 iterations, 4 same-name repeats); this bounds the burst inside it.
716	 * The rule itself lives in vg_agent_query.c so host tests can drive it.
717	 */
718	
719	#define VG_TOOL_RATE_WINDOW_MS 60000u
720	#define VG_TOOL_RATE_MAX_CALLS 20
721	
722	static struct vg_agent_rate g_rate;
723	
724	static uint32_t rate_now_ms(void)
725	{
726	  struct timespec ts;
727	
728	  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
729	    {
730	      return 0;
731	    }
732	
733	  return (uint32_t)((uint64_t)ts.tv_sec * 1000u
734	                    + (uint64_t)ts.tv_nsec / 1000000u);
735	}
736	
737	static int vg_tools_execute(const char *name, const char *input_json,
738	                            char *output, size_t output_size)
739	{
740	  size_t cap;
741	
742	  /* input_json is read by vg_point_read and vg_alarm_recovery. */
743	
744	  if (name == NULL || output == NULL || output_size == 0)
745	    {
746	      return ERROR;
747	    }
748	
749	  cap = (output_size > VG_AGENT_TOOL_OUT_MAX)
750	            ? VG_AGENT_TOOL_OUT_MAX
751	            : output_size;
752	
753	  output[0] = '\0';
754	
755	  /* Only count calls we actually own, so a probe for someone else's tool does
756	   * not spend this provider's budget, and a tool this build did not compile
757	   * in is not claimed at all. */
758	  {
759	    bool owned = false;
760	
761	#ifdef VG_AGENT_TOOLS_HAVE_POINTS
762	    if (strcmp(name, "vg_point_read") == 0)
763	      {
764	        owned = true;
765	      }
766	#endif
767	
768	#ifdef VG_AGENT_TOOLS_HAVE_REPORT
769	    if (strcmp(name, "vg_run_report") == 0 ||
770	        strcmp(name, "vg_anomaly_read") == 0 ||
771	        strcmp(name, "vg_alarm_recovery") == 0)
772	      {
773	        owned = true;
774	      }
775	#endif
776	
777	    if (!owned)
778	      {
779	        return ERROR;
780	      }
781	  }
782	
783	  if (!vg_agent_rate_allow(&g_rate, rate_now_ms()))
784	    {
785	      /* OK, not ERROR: the registry reads a provider's ERROR as "not my
786	       * tool", skips to the next provider and finally overwrites this buffer
787	       * with "unknown tool".  A rate-limited call would then reach the model
788	       * as a tool that does not exist, and it would keep retrying instead of
789	       * waiting.  Only a name we do not own may return ERROR. */
790	      snprintf(output, cap,
791	               "vgquery: reason=rate_limited msg=调用过于频繁，请稍后再试\n");
792	      return OK;
793	    }
794	
795	#ifdef VG_AGENT_TOOLS_HAVE_POINTS
796	  if (strcmp(name, "vg_point_read") == 0)
797	    {
798	      char query[VG_AGENT_TOOL_QUERY_MAX];
799	      const char *q = NULL;
800	      int rc;
801	
802	      rc = parse_query(input_json, query, sizeof(query), &q);
803	
804	      if (rc == -E2BIG)
805	        {
806	          snprintf(output, cap,
807	                   "vgquery: reason=bad_arg msg=query 过长，上限 %d 字节\n",
808	                   VG_AGENT_TOOL_QUERY_MAX - 1);
809	          return OK;
810	        }
811	
812	      if (rc != 0)
813	        {
814	          snprintf(output, cap,
815	                   "vgquery: reason=bad_arg msg=query 必须是字符串\n");
816	          return OK;
817	        }
818	
819	      return tool_point_read(q, output, cap);
820	    }
821	#endif
822	
823	#ifdef VG_AGENT_TOOLS_HAVE_REPORT
824	  if (strcmp(name, "vg_run_report") == 0)
825	    {
826	      return tool_run_report(output, cap);
827	    }
828	
829	  if (strcmp(name, "vg_anomaly_read") == 0)
830	    {
831	      return tool_anomaly_read(output, cap);
832	    }
833	
834	  if (strcmp(name, "vg_alarm_recovery") == 0)
835	    {
836	      return tool_alarm_recovery(input_json, output, cap);
837	    }
838	#endif
839	
840	  /* Not ours: let the registry try the next provider. */
841	  return ERROR;
842	}
843	
844	#endif /* any tool */
