847	
848	#ifdef VG_AGENT_TOOLS_HOST_TEST
849	/* The host suite runs many calls back to back, far faster than the product
850	 * ever will, so it resets the window between cases.  Compiled only for the
851	 * test build: the firmware has no way to clear the limit. */
852	
853	void vg_agent_tools_reset_rate(void)
854	{
855	  vg_agent_rate_init(&g_rate, VG_TOOL_RATE_MAX_CALLS, VG_TOOL_RATE_WINDOW_MS);
856	}
857	#endif
858	
859	void vg_agent_tools_register(void)
860	{
861	#if defined(VG_AGENT_TOOLS_HAVE_POINTS) || defined(VG_AGENT_TOOLS_HAVE_REPORT)
862	  static bool registered;
863	
864	  if (registered)
865	    {
866	      return;
867	    }
868	
869	  tool_registry_register_provider("vg", vg_tools_get_json, vg_tools_execute);
870	  vg_agent_rate_init(&g_rate, VG_TOOL_RATE_MAX_CALLS, VG_TOOL_RATE_WINDOW_MS);
871	  registered = true;
872	#endif
