1	/****************************************************************************
2	 * app/velaguard/vg_voice_facts.h
3	 *
4	 * BVO-10: the snapshot a spoken answer is built from.
5	 *
6	 * Tools publish what they read under one sequence number. A voice round
7	 * performs its resolved read with a thread-owned capture, then renders both
8	 * display and speech from that private copy. Model prose is not displayed.
9	 *
10	 * The snapshot is process memory, replaced as a whole.  It is not a log and
11	 * is never written to eMMC.
12	 ****************************************************************************/
13	
14	#ifndef __APP_VELAGUARD_VG_VOICE_FACTS_H
