22	struct vg_voice_facts
23	{
24	  uint32_t seq;             /* bumped on every publish */
25	  uint32_t boot_id;
26	  uint32_t config_version;
27	  uint32_t data_age_ms;     /* age of the live snapshot this came from */
28	
29	  /* Anomaly answer. */
30	  int      anomaly_total;   /* points, including those beyond anomaly_n */
31	  int      anomaly_seen;    /* points the runtime has sampled at least once */
32	  int      anomaly_n;
33	  struct vg_runtime_anomaly anomalies[VG_RUNTIME_MAX_POINTS];
34	
35	  /* Recovery answer. */
36	  bool     has_recovery;
37	  struct vg_runtime_recovery recovery;
38	
39	  /* Point answer. */
40	  bool     has_point;
41	  char     point_id[48];
42	  char     point_name[48];
43	  char     point_unit[8];
44	  bool     point_online;
45	  bool     point_has_value;
46	  float    point_value;
47	  uint32_t point_age_ms;
48	  char     point_cmp[4];
49	  bool     point_has_warn;
50	  float    point_warn;
51	  bool     point_has_crit;
52	  float    point_crit;
53	};
