5	#include <nuttx/config.h>
6	
7	#ifdef CONFIG_EXAMPLES_AI_AGENT_VELA
8	
9	#include <errno.h>
10	#include <pthread.h>
11	#include <string.h>
12	#include <syslog.h>
13	#include <time.h>
14	
15	#include <velaclaw/client.h>
16	
17	#include "vg_agent_round.h"
18	
19	#define TAG "vgagent"
20	
21	#define VG_ROUND_REQ_MAX   1536
22	#define VG_ROUND_REPLY_MAX 192
23	
24	static pthread_mutex_t g_lock = PTHREAD_MUTEX_INITIALIZER;
25	
26	static velaclaw_client_t          *g_client;
27	static enum vg_agent_round_state   g_state = VG_AGENT_ROUND_IDLE;
28	static uint32_t                    g_started_ms;
29	static uint32_t                    g_deadline_ms;
30	static uint32_t                    g_generation;
31	static uint32_t                    g_request_serial;
32	static bool                        g_reply_seen;
33	static bool                        g_reply_ok;
34	static bool                        g_submitting;
35	static enum vg_agent_round_owner   g_owner;
36	static uint32_t                    g_finished_ms;
37	
38	static char g_req[VG_ROUND_REQ_MAX];
39	static char g_reply[VG_ROUND_REPLY_MAX];
40	static bool g_suspended;
41	static bool g_voice_foreground;
42	static enum vg_agent_round_owner g_suspended_owner;
43	static char g_suspended_req[VG_ROUND_REQ_MAX];
44	
45	/* 语音可挂起一条后台请求，先取消后台传输，播报结束后再以原请求排队。 */
46	static void restore_background_locked(void)
47	{
48	  if (!g_suspended || g_voice_foreground)
49	    {
50	      return;
51	    }
52	  if (++g_request_serial == 0) ++g_request_serial;
53	  memcpy(g_req, g_suspended_req, sizeof(g_req));
54	  memset(g_suspended_req, 0, sizeof(g_suspended_req));
55	  g_owner = g_suspended_owner;
56	  syslog(LOG_INFO,"[%s] resumed background owner=%u\n",TAG,(unsigned)g_owner);
57	  g_suspended = false;
58	  g_deadline_ms = 0;
59	  g_state = VG_AGENT_ROUND_QUEUED;
60	  g_started_ms = vg_agent_round_now_ms();
61	  g_finished_ms = 0;
62	  g_reply_seen = false;
63	  g_reply_ok = false;
64	  g_reply[0] = '\0';
65	}
66	
67	uint32_t vg_agent_round_now_ms(void)
68	{
69	  struct timespec ts;
70	
71	  (void)clock_gettime(CLOCK_MONOTONIC, &ts);
72	  return (uint32_t)((uint64_t)ts.tv_sec * 1000u
73	                    + (uint64_t)ts.tv_nsec / 1000000u);
74	}
75	
76	/* Runs on the agent's outbound dispatch thread, so it only records the
77	 * outcome and never blocks on anything but this mutex. */
78	
79	static void round_reply(int status, const char *text, void *cookie)
80	{
81	  pthread_mutex_lock(&g_lock);
82	  if ((uint32_t)(uintptr_t)cookie != g_request_serial ||
83	      (g_state != VG_AGENT_ROUND_QUEUED && g_state != VG_AGENT_ROUND_RUNNING))
84	    { pthread_mutex_unlock(&g_lock); return; }
85	  g_reply_seen = true;
86	  g_reply_ok = (status == 0);
87	
88	  if (text != NULL)
89	    {
90	      strncpy(g_reply, text, sizeof(g_reply) - 1);
91	      g_reply[sizeof(g_reply) - 1] = '\0';
92	    }
93	  else
94	    {
95	      g_reply[0] = '\0';
96	    }
97	
98	  pthread_mutex_unlock(&g_lock);
99	}
100	
101	int vg_agent_round_init(void)
102	{
103	  int rc = 0;
104	
105	  pthread_mutex_lock(&g_lock);
106	
107	  if (g_client == NULL)
108	    {
109	      /* Fails while the agent's message bus is still coming up; the worker
110	       * retries on later ticks until VG_AGENT_ROUND_QUEUE_TIMEOUT_MS. */
111	
112	      g_client = velaclaw_client_open("velaguard");
113	      if (g_client != NULL)
114	        {
115	          syslog(LOG_INFO, "[%s] local agent client ready\n", TAG);
116	        }
117	    }
118	
119	  if (g_client == NULL)
120	    {
121	      rc = -ENODEV;
122	    }
123	
124	  pthread_mutex_unlock(&g_lock);
125	  return rc;
126	}
127	
128	int vg_agent_round_queue(const char *text)
129	{
130	  return vg_agent_round_queue_owned(text, VG_AGENT_ROUND_OWNER_NONE);
131	}
132	
133	static int round_queue(const char *text,
134	                       enum vg_agent_round_owner owner, uint32_t deadline_ms)
135	{
136	  size_t len;
137	
138	  if (text == NULL)
139	    {
140	      return -EINVAL;
141	    }
142	
143	  len = strlen(text);
144	  if (len == 0)
145	    {
146	      return -EINVAL;
147	    }
148	
149	  if (len >= VG_ROUND_REQ_MAX)
150	    {
151	      return -E2BIG;
152	    }
153	
154	  pthread_mutex_lock(&g_lock);
155	
156	  /* A finished result that its owner has not read yet is not free: letting
157	   * another flow overwrite it would discard an artifact that is already on
158	   * eMMC.  Both consumers clear their own result within a tick, so this only
159	   * ever costs the new request one worker iteration. */
160	
161	  if (owner != VG_AGENT_ROUND_OWNER_VOICE && g_voice_foreground)
162	    { pthread_mutex_unlock(&g_lock); return -EBUSY; }
163	
164	  if (g_state != VG_AGENT_ROUND_IDLE)
165	    {
166	      if (owner == VG_AGENT_ROUND_OWNER_VOICE &&
167	          (g_state == VG_AGENT_ROUND_QUEUED || g_state == VG_AGENT_ROUND_RUNNING) &&
168	          !g_submitting && !g_suspended &&
169	          (g_owner == VG_AGENT_ROUND_OWNER_ADVICE ||
170	           g_owner == VG_AGENT_ROUND_OWNER_DAILY))
171	        {
172	          memcpy(g_suspended_req, g_req, sizeof(g_req));
173	          g_suspended_owner = g_owner;
174	          g_suspended = true;
175	          syslog(LOG_INFO,"[%s] paused background owner=%u for voice\n",TAG,(unsigned)g_owner);
176	          if (g_state == VG_AGENT_ROUND_RUNNING && g_client != NULL)
177	            velaclaw_client_abandon(g_client);
178	        }
179	      else
180	        {
181	          pthread_mutex_unlock(&g_lock);
182	          return -EBUSY;
183	        }
184	    }
185	
186	  if (++g_request_serial == 0) ++g_request_serial;
187	  memcpy(g_req, text, len + 1);
188	  g_owner = owner;
189	  if (owner == VG_AGENT_ROUND_OWNER_VOICE) g_voice_foreground = true;
190	  g_deadline_ms = deadline_ms;
191	  g_state = VG_AGENT_ROUND_QUEUED;
192	  g_started_ms = vg_agent_round_now_ms();
193	  g_reply_seen = false;
194	  g_reply_ok = false;
195	  g_reply[0] = '\0';
196	
197	  pthread_mutex_unlock(&g_lock);
198	  return 0;
199	}
200	
201	int vg_agent_round_queue_owned(const char *text,
202	                               enum vg_agent_round_owner owner)
203	{
204	  return round_queue(text, owner, 0);
205	}
206	
207	int vg_agent_round_queue_voice(const char *text, uint32_t deadline_ms)
208	{
209	  if (deadline_ms == 0 ||
210	      (int32_t)(deadline_ms - vg_agent_round_now_ms()) <= 0)
211	    {
212	      return -ETIMEDOUT;
213	    }
214	  return round_queue(text, VG_AGENT_ROUND_OWNER_VOICE, deadline_ms);
215	}
216	
217	uint32_t vg_agent_round_voice_serial(void)
218	{
219	  pthread_mutex_lock(&g_lock);
220	  uint32_t serial = g_owner == VG_AGENT_ROUND_OWNER_VOICE &&

220	  uint32_t serial = g_owner == VG_AGENT_ROUND_OWNER_VOICE &&
221	                    (g_state == VG_AGENT_ROUND_QUEUED ||
222	                     g_state == VG_AGENT_ROUND_RUNNING) ? g_request_serial : 0;
223	  pthread_mutex_unlock(&g_lock);
