226	
227	/* ASR 也占用前台预算；先暂停后台，避免识别上传与后台模型争用网络。 */
228	int vg_agent_round_voice_reserve(void)
229	{
230	  pthread_mutex_lock(&g_lock);
231	  if (g_state != VG_AGENT_ROUND_IDLE)
232	    {
233	      if ((g_state != VG_AGENT_ROUND_QUEUED && g_state != VG_AGENT_ROUND_RUNNING) ||
234	          g_submitting || g_suspended ||
235	          (g_owner != VG_AGENT_ROUND_OWNER_ADVICE && g_owner != VG_AGENT_ROUND_OWNER_DAILY))
236	        { pthread_mutex_unlock(&g_lock); return -EBUSY; }
237	      memcpy(g_suspended_req, g_req, sizeof(g_req));
238	      g_suspended_owner = g_owner;
239	      g_suspended = true;
240	      if (g_state == VG_AGENT_ROUND_RUNNING && g_client != NULL)
241	        velaclaw_client_abandon(g_client);
242	      if (++g_request_serial == 0) ++g_request_serial;
243	      syslog(LOG_INFO,"[%s] paused background owner=%u before ASR\n",TAG,(unsigned)g_owner);
244	      g_state = VG_AGENT_ROUND_IDLE;
245	      g_owner = VG_AGENT_ROUND_OWNER_NONE;
246	    }
247	  g_voice_foreground = true;
248	  pthread_mutex_unlock(&g_lock);
249	  return 0;
250	}
251	
252	void vg_agent_round_voice_release(void)
253	{
254	  pthread_mutex_lock(&g_lock);
255	  g_voice_foreground = false;
256	  if (g_state == VG_AGENT_ROUND_IDLE) restore_background_locked();
257	  pthread_mutex_unlock(&g_lock);
258	}
259	
260	static void round_submit(void)
261	{
262	  /* Function-local so a 1.5 KB request never lands on the worker stack, and
263	   * released before the call so the reply callback can never contend with us
264	   * on the same lock if a build ever dispatches replies synchronously. */
265	
266	  static char req[VG_ROUND_REQ_MAX];
267	  velaclaw_client_t *client;
268	  velaclaw_ask_req_t ask;
269	  int rc;
270	  uint32_t serial;
271	  uint32_t deadline;
272	
273	  pthread_mutex_lock(&g_lock);
274	  if (g_client == NULL)
275	    {
276	      pthread_mutex_unlock(&g_lock);
277	
278	      if (vg_agent_round_init() != 0)
279	        {
280	          return;
281	        }
282	
283	      pthread_mutex_lock(&g_lock);
284	    }
285	
286	  client = g_client;
287	  memcpy(req, g_req, sizeof(req));
288	  serial = g_request_serial;
289	  deadline = g_deadline_ms;
290	  pthread_mutex_unlock(&g_lock);
291	
292	  ask.text = req;
293	  ask.timeout_ms = (int)VG_AGENT_ROUND_TIMEOUT_MS;
294	
295	  if (deadline != 0)
296	    {
297	      int32_t remaining = (int32_t)(deadline - vg_agent_round_now_ms());
298	      ask.timeout_ms = remaining > 0 ? remaining : 1;
299	      rc = velaclaw_ask_async_deadline(client, &ask, deadline, round_reply,
300	                                      (void *)(uintptr_t)serial);
301	    }
302	  else
303	    {
304	      uint32_t background_deadline = vg_agent_round_now_ms() + VG_AGENT_ROUND_TIMEOUT_MS;
305	      if (!background_deadline) background_deadline = 1;
306	      rc = velaclaw_ask_async_background(client, &ask, background_deadline,
307	                                        round_reply, (void *)(uintptr_t)serial);
308	    }
309	
310	  pthread_mutex_lock(&g_lock);
311	
312	  if (serial != g_request_serial)
313	    {
314	      if (rc == 0)
315	        {
316	          velaclaw_client_abandon(client);
317	        }
318	      pthread_mutex_unlock(&g_lock);
319	      return;
320	    }
321	
322	  /* abandon() may have run while velaclaw_ask_async was in flight.  In that
323	   * case the question is gone: leave the state IDLE instead of resurrecting
324	   * it, or the next question is refused as busy.  The reply is dropped by
325	   * its serial either way. */
326	
327	  if (rc == 0 && g_state == VG_AGENT_ROUND_QUEUED &&
328	      serial == g_request_serial)
329	    {
330	      g_state = VG_AGENT_ROUND_RUNNING;
331	      g_started_ms = vg_agent_round_now_ms();
332	      syslog(LOG_INFO, "[%s] round submitted: %u bytes\n",
333	             TAG, (unsigned)strlen(req));
334	    }
335	  else if (rc == 0)
336	    {
337	      velaclaw_client_abandon(client);
338	      syslog(LOG_INFO, "[%s] round abandoned during submit\n", TAG);
339	    }
340	  else if (rc == -EBUSY)
341	    {
342	      /* The channel already carries a background round.  A user question
343	       * waits behind it instead of failing on the spot: the state stays
344	       * QUEUED and later ticks retry until the queue timeout. */
345	
346	    }
347	  else
348	    {
349	      g_state = VG_AGENT_ROUND_ERROR;
350	      g_finished_ms = vg_agent_round_now_ms();
351	      syslog(LOG_WARNING, "[%s] round submit failed: %d\n", TAG, rc);
352	    }
353	
354	  pthread_mutex_unlock(&g_lock);
355	}
356	
357	void vg_agent_round_tick(void)
358	{
359	  pthread_mutex_lock(&g_lock);
360	  if (g_state == VG_AGENT_ROUND_QUEUED)
361	    {
362	      if (g_submitting) { pthread_mutex_unlock(&g_lock); return; }
363	      g_submitting = true;
364	      pthread_mutex_unlock(&g_lock);
365	      round_submit();
366	      pthread_mutex_lock(&g_lock);
367	      g_submitting = false;
368	      if (g_state == VG_AGENT_ROUND_QUEUED &&
369	          (int32_t)(vg_agent_round_now_ms() - g_started_ms) >=
370	          (int32_t)VG_AGENT_ROUND_QUEUE_TIMEOUT_MS)
371	        {
372	          g_state = VG_AGENT_ROUND_ERROR;
373	          g_finished_ms = vg_agent_round_now_ms();
374	          syslog(LOG_WARNING, "[%s] round never reached the agent\n", TAG);
375	        }
376	      pthread_mutex_unlock(&g_lock);
377	      return;
378	    }
379	  if (g_state != VG_AGENT_ROUND_RUNNING)
380	    { pthread_mutex_unlock(&g_lock); return; }
381	
382	  uint32_t now = vg_agent_round_now_ms();
383	  if (g_reply_seen)
384	    {
385	      bool ok = g_reply_ok;
386	      g_reply_seen = false;
387	      g_state = ok ? VG_AGENT_ROUND_DONE : VG_AGENT_ROUND_ERROR;
388	      if (ok) g_generation++;
389	      g_finished_ms = now;
390	      pthread_mutex_unlock(&g_lock);
391	      syslog(LOG_INFO, "[%s] round finished: %s\n", TAG, ok ? "reply" : "agent error");
392	      return;
393	    }
394	  if ((g_deadline_ms != 0 && (int32_t)(now - g_deadline_ms) >= 0) ||
395	      (int32_t)(now - g_started_ms) >= (int32_t)VG_AGENT_ROUND_TIMEOUT_MS)
396	    {
397	      g_state = VG_AGENT_ROUND_ERROR;
398	      g_finished_ms = now;
399	      velaclaw_client_abandon(g_client);
400	      pthread_mutex_unlock(&g_lock);
401	      syslog(LOG_WARNING, "[%s] round timed out\n", TAG);
402	      return;
403	    }
404	  pthread_mutex_unlock(&g_lock);
405	}
406	
407	enum vg_agent_round_state vg_agent_round_state(void)
408	{
409	  enum vg_agent_round_state st;
410	
411	  pthread_mutex_lock(&g_lock);
412	  st = g_state;
413	  pthread_mutex_unlock(&g_lock);
414	  return st;
415	}
