493	static void round_abandon(bool check_owner, enum vg_agent_round_owner owner)
494	{
495	  pthread_mutex_lock(&g_lock);
496	  if (check_owner && g_owner != owner)
497	    {
498	      pthread_mutex_unlock(&g_lock);
499	      return;
500	    }
501	
502	  if (g_state != VG_AGENT_ROUND_IDLE)
503	    {
504	      if (g_owner == VG_AGENT_ROUND_OWNER_VOICE)
505	        {
506	          memset(g_req, 0, sizeof(g_req));
507	          memset(g_reply, 0, sizeof(g_reply));
508	        }
509	      g_state = VG_AGENT_ROUND_IDLE;
510	      g_owner = VG_AGENT_ROUND_OWNER_NONE;
511	      g_finished_ms = 0;
512	      g_deadline_ms = 0;
513	      g_reply_seen = false;
514	      if (++g_request_serial == 0)
515	        {
516	          ++g_request_serial;
517	        }
518	    }
519	
520	  /* Keep cancellation atomic with owner/state changes.  The client releases
521	   * its own mutex before invoking round_reply, so this lock order is safe. */
522	  if (g_client != NULL)
523	    {
524	      velaclaw_client_abandon(g_client);
525	    }
526	  restore_background_locked();
527	  pthread_mutex_unlock(&g_lock);
528	}
