13	/* Wrap-safe elapsed test.  The board clock is 32-bit milliseconds and wraps
14	 * roughly every 49 days; a plain "now >= start + limit" would break there. */
15	
16	static bool reached(uint32_t now, uint32_t start, uint32_t limit)
17	{
18	  return (int32_t)(now - start) >= (int32_t)limit;
19	}
20	
21	static uint32_t elapsed(uint32_t now, uint32_t start)
22	{
23	  int32_t d = (int32_t)(now - start);
24	
25	  return (d > 0) ? (uint32_t)d : 0;
26	}
