28	static void copy_str(char *dst, size_t cap, const char *src)
29	{
30	  if (dst == NULL || cap == 0)
31	    {
32	      return;
33	    }
34	
35	  if (src == NULL)
36	    {
37	      dst[0] = '\0';
38	      return;
39	    }
40	
41	  strncpy(dst, src, cap - 1);
42	  dst[cap - 1] = '\0';
43	}
