51	static uint32_t cancel_actions(enum vg_vs_state st)
52	{
53	  switch (st)
54	    {
55	      case VG_VS_RECORDING:
56	      case VG_VS_STOPPING:
57	        return VG_VS_ACT_STOP_RECORD;
58	
59	      case VG_VS_ASR:
60	        return VG_VS_ACT_CANCEL_ASR;
61	
62	      case VG_VS_WAIT_AGENT:
63	      case VG_VS_QUERYING:
64	        return VG_VS_ACT_CANCEL_AGENT;
65	
66	      case VG_VS_TTS:
67	        return VG_VS_ACT_STOP_TTS;
68	
69	      case VG_VS_PLAYING:
70	        return VG_VS_ACT_STOP_PLAYBACK;
71	
72	      default:
73	        return 0;
74	    }
75	}
