110	uint32_t vg_vs_press(struct vg_voice_session *s, uint32_t now_ms)
111	{
112	  uint32_t actions = 0;
113	  enum vg_vs_state prev;
114	
115	  if (s == NULL)
116	    {
117	      return 0;
118	    }
119	
120	  s->now_ms = now_ms;
121	  prev = s->state;
122	
123	  /* One physical press is already one begin; a second press while the
124	   * recorder is open is either a bounce or a press the button layer has
125	   * already coalesced. */
126	
127	  if (prev == VG_VS_RECORDING || prev == VG_VS_STOPPING)
128	    {
129	      return 0;
130	    }
131	
132	  /* Any press abandons the previous question.  The generation bump makes
133	   * every outstanding result stale before the new recording starts. */
134	
135	  actions |= cancel_actions(prev);
136	  s->generation++;
137	
138	  if (prev == VG_VS_PLAYING)
139	    {
140	      /* Capture and playback share the audio device: wait for the real stop
141	       * before asking for the recorder. */
142	
143	      s->state = VG_VS_STOPPING;
144	      return actions | VG_VS_ACT_STOP_PLAYBACK;
145	    }
146	
147	  if (prev == VG_VS_RESULT || prev == VG_VS_ERROR || prev == VG_VS_IDLE)
148	    {
149	      actions |= VG_VS_ACT_HIDE_OVERLAY;
150	    }
151	
152	  s->speech_failed = false;
153	  s->have_answer = false;
154	  s->answer[0] = '\0';
155	  s->state = VG_VS_RECORDING;
156	  s->record_ms = now_ms;
157	  s->last_active_ms = now_ms;
158	
159	  return actions | VG_VS_ACT_START_RECORD;
160	}
161	
162	uint32_t vg_vs_release(struct vg_voice_session *s, uint32_t now_ms)
163	{
164	  uint32_t dur;
165	
166	  if (s == NULL || s->state != VG_VS_RECORDING)
167	    {
168	      return 0;
169	    }
170	
171	  s->now_ms = now_ms;
172	  dur = elapsed(now_ms, s->record_ms);
173	
174	  if (dur < VG_VS_RECORD_MIN_MS)
175	    {
176	      /* Half a press is not a question.  Drop the buffer and say so. */
177	
178	      s->state = VG_VS_ERROR;
179	      s->error_ms = now_ms;
180	      s->last_active_ms = now_ms;
181	      s->generation++;
182	      copy_str(s->answer, sizeof(s->answer), "recording too short");
183	      return VG_VS_ACT_STOP_RECORD | VG_VS_ACT_SHOW_ERROR;
184	    }
185	
186	  s->state = VG_VS_ASR;
187	  s->submit_ms = now_ms;
188	  s->budget_ms = VG_VS_BUDGET_MS;
189	  s->deadline_ms = now_ms + VG_VS_BUDGET_MS;
190	  s->last_active_ms = now_ms;
191	
192	  return VG_VS_ACT_STOP_RECORD | VG_VS_ACT_START_ASR;
193	}
