195	uint32_t vg_vs_record_cap(struct vg_voice_session *s, uint32_t now_ms)
196	{
197	  if (s == NULL || s->state != VG_VS_RECORDING)
198	    {
199	      return 0;
200	    }
201	
202	  if (!reached(now_ms, s->record_ms, VG_VS_RECORD_MAX_MS))
203	    {
204	      return 0;
205	    }
206	
207	  /* The cap submits exactly like a release; the button layer keeps the press
208	   * gated until the key is released, so this cannot repeat. */
209	
210	  s->now_ms = now_ms;
211	  s->state = VG_VS_ASR;
212	  s->submit_ms = now_ms;
213	  s->budget_ms = VG_VS_BUDGET_MS;
214	  s->deadline_ms = now_ms + VG_VS_BUDGET_MS;
215	  s->last_active_ms = now_ms;
216	
217	  return VG_VS_ACT_STOP_RECORD | VG_VS_ACT_START_ASR;
218	}
