242	  s->now_ms = now_ms;
243	
244	  if (!ok)
245	    {
246	      s->state = VG_VS_ERROR;
247	      s->error_ms = now_ms;
248	      s->last_active_ms = now_ms;
249	      s->generation++;
250	      copy_str(s->answer, sizeof(s->answer), "speech recognition failed");
251	      return VG_VS_ACT_SHOW_ERROR;
252	    }
253	
254	  if (text == NULL || text[0] == '\0')
255	    {
256	      /* An empty transcript is a real result, not a failure to retry: asking
257	       * the agent about nothing would waste a round and answer nothing. */
258	
259	      s->state = VG_VS_ERROR;
260	      s->error_ms = now_ms;
261	      s->last_active_ms = now_ms;
262	      s->generation++;
263	      copy_str(s->answer, sizeof(s->answer), "no speech recognized");
264	      return VG_VS_ACT_SHOW_ERROR;
265	    }
266	
267	  copy_str(s->text, sizeof(s->text), text);
268	  s->state = VG_VS_WAIT_AGENT;
