287	uint32_t vg_vs_agent_result(struct vg_voice_session *s, uint32_t generation,
288	                            bool ok, const char *answer, uint32_t now_ms)
289	{
290	  if (s == NULL ||
291	      (s->state != VG_VS_WAIT_AGENT && s->state != VG_VS_QUERYING) ||
292	      generation != s->generation)
293	    {
294	      return 0;
295	    }
296	
297	  s->now_ms = now_ms;
298	
299	  if (!ok || answer == NULL || answer[0] == '\0')
300	    {
301	      s->state = VG_VS_ERROR;
302	      s->error_ms = now_ms;
303	      s->last_active_ms = now_ms;
304	      s->generation++;
305	      copy_str(s->answer, sizeof(s->answer), "answer unavailable");
306	      return VG_VS_ACT_SHOW_ERROR;
307	    }
308	
309	  copy_str(s->answer, sizeof(s->answer), answer);
310	  s->have_answer = true;
311	  s->last_active_ms = now_ms;
312	
313	  if (s->muted)
314	    {
315	      /* Muted: the text is the whole answer, so no TTS request is made. */
316	
317	      s->state = VG_VS_RESULT;
318	      s->result_ms = now_ms;
319	      s->held = false;
320	      s->speech_failed = false;
321	      s->generation++;
322	      return VG_VS_ACT_SHOW_RESULT;
323	    }
324	
325	  s->state = VG_VS_TTS;
326	  s->speech_failed = false;
327	  /* 查询已给出有效文字，合成完整音频另给有限窗口。保留 submit_ms
328	   * 作为整轮计时锚点，避免慢查询挤占合成时间并截断已开始的播报。 */
329	
330	  s->budget_ms = elapsed(now_ms, s->submit_ms) + VG_VS_TTS_BUDGET_MS;
331	  s->deadline_ms = now_ms + VG_VS_TTS_BUDGET_MS;
332	  return VG_VS_ACT_START_TTS;
333	}
