341	    }
342	
343	  s->now_ms = now_ms;
344	
345	  if (!ok)
346	    {
347	      /* The answer itself is still valid.  Keep it on screen and offer a
348	       * playback retry; do not run the agent again. */
349	
350	      s->state = VG_VS_RESULT;
351	      s->result_ms = now_ms;
352	      s->held = false;
353	      s->speech_failed = true;
354	      s->last_active_ms = now_ms;
355	      s->generation++;
356	      return VG_VS_ACT_SHOW_RESULT;
357	    }
