382	uint32_t vg_vs_retry_tts(struct vg_voice_session *s, uint32_t now_ms)
383	{
384	  if (s == NULL || s->state != VG_VS_RESULT || !s->have_answer ||
385	      !s->speech_failed || s->muted)
386	    {
387	      return 0;
388	    }
389	
390	  s->now_ms = now_ms;
391	  s->state = VG_VS_TTS;
392	
393	  /* The first deadline has already been spent, so reusing it would make the
394	   * retry button dead on arrival.  A retry is a new user action: give the
395	   * speech stage its own bounded budget and restart the shared deadline at
396	   * that smaller value. */
397	
398	  s->submit_ms = now_ms;
399	  s->budget_ms = VG_VS_RETRY_BUDGET_MS;
400	  s->deadline_ms = now_ms + VG_VS_RETRY_BUDGET_MS;
401	  s->speech_failed = false;
402	  s->generation++;
403	  return VG_VS_ACT_START_TTS;
404	}
405	
406	uint32_t vg_vs_tick(struct vg_voice_session *s, uint32_t now_ms)
407	{
408	  uint32_t actions = 0;
409	
410	  if (s == NULL)
411	    {
412	      return 0;
413	    }
414	
415	  s->now_ms = now_ms;
416	
417	  if (s->state == VG_VS_RECORDING)
418	    {
419	      return vg_vs_record_cap(s, now_ms);
420	    }
421	
422	  if (in_flight(s->state) && reached(now_ms, s->submit_ms, s->budget_ms))
423	    {
424	      /* ASR/query share one deadline; TTS has a bounded window after text. */
425	
426	      actions |= cancel_actions(s->state);
427	
428	      if (s->state == VG_VS_TTS && s->have_answer)
429	        {
430	          s->state = VG_VS_RESULT;
431	          s->result_ms = now_ms;
432	          s->held = false;
433	          s->speech_failed = true;
434	          s->last_active_ms = now_ms;
435	          s->generation++;
436	          return actions | VG_VS_ACT_SHOW_RESULT;
437	        }
438	
439	      s->state = VG_VS_ERROR;
440	      s->error_ms = now_ms;
441	      s->last_active_ms = now_ms;
442	      s->generation++;
443	      copy_str(s->answer, sizeof(s->answer), "timed out");
444	      return actions | VG_VS_ACT_SHOW_ERROR;
445	    }
446	
447	  if (s->state == VG_VS_RESULT && !s->held &&
448	      reached(now_ms, s->result_ms, VG_VS_RESULT_HOLD_MS))
449	    {
450	      /* Hiding is a display event only; the context survives so a follow-up
451	       * can still name the last point. */
452	
453	      s->state = VG_VS_IDLE;
454	      s->last_active_ms = now_ms;
455	      s->generation++;
456	      return VG_VS_ACT_HIDE_OVERLAY;
457	    }
458	
459	  if ((s->state == VG_VS_IDLE || s->state == VG_VS_RESULT ||
460	       s->state == VG_VS_ERROR) &&
461	      reached(now_ms, s->last_active_ms, VG_VS_IDLE_MS))
462	    {
463	      clear_context(s);
464	      s->have_answer = false;
465	      s->answer[0] = '\0';
466	      s->speech_failed = false;
467	
468	      if (s->state != VG_VS_IDLE)
469	        {
470	          s->state = VG_VS_IDLE;
471	          s->generation++;
472	        }
473	      actions |= VG_VS_ACT_HIDE_OVERLAY;
474	    }
475	
476	  return actions;
477	}
478	
479	void vg_vs_result_hold(struct vg_voice_session *s, bool held, uint32_t now_ms)
480	{
481	  if (s == NULL || s->state != VG_VS_RESULT)
482	    {
483	      return;
484	    }
485	
486	  if (held && !s->held)
487	    {
488	      s->held = true;
489	      return;
490	    }
491	
492	  if (!held && s->held)
493	    {
494	      /* Restart the full window: the reader scrolled, so the time spent
495	       * reading must not count against the answer. */
496	
497	      s->held = false;
498	      s->result_ms = now_ms;
499	    }
500	}
501	
502	uint32_t vg_vs_end(struct vg_voice_session *s, uint32_t now_ms)
503	{
504	  uint32_t actions;
505	
506	  if (s == NULL)
507	    {
508	      return 0;
509	    }
510	
511	  actions = cancel_actions(s->state);
512	
513	  /* Ending also clears a previously hidden answer held by the overlay. */
514	  actions |= VG_VS_ACT_HIDE_OVERLAY;
515	
516	  if (s->state == VG_VS_PLAYING || s->state == VG_VS_TTS)
517	    {
518	      actions |= VG_VS_ACT_RELEASE_AUDIO;
519	    }
520	
521	  clear_context(s);
522	  s->answer[0] = '\0';
523	  s->have_answer = false;
524	  s->speech_failed = false;
525	  s->state = VG_VS_IDLE;
526	  s->now_ms = now_ms;
527	  s->last_active_ms = now_ms;
528	  s->generation++;
529	  return actions;
530	}
