591	uint32_t vg_vs_remaining_ms(const struct vg_voice_session *s, uint32_t now_ms)
592	{
593	  if (s == NULL || !in_flight(s->state))
594	    {
595	      return 0;
596	    }
597	
598	  if (reached(now_ms, s->submit_ms, s->budget_ms))
599	    {
600	      return 0;
601	    }
602	
603	  return s->budget_ms - elapsed(now_ms, s->submit_ms);
604	}
605	
606	uint32_t vg_vs_result_left_s(const struct vg_voice_session *s, uint32_t now_ms)
607	{
608	  uint32_t used;
609	
610	  if (s == NULL || s->state != VG_VS_RESULT)
611	    {
612	      return 0;
613	    }
614	
615	  if (s->held)
616	    {
617	      return VG_VS_RESULT_HOLD_MS / 1000u;
618	    }
619	
620	  used = elapsed(now_ms, s->result_ms);
621	  if (used >= VG_VS_RESULT_HOLD_MS)
622	    {
623	      return 0;
624	    }
625	
626	  return (VG_VS_RESULT_HOLD_MS - used + 999u) / 1000u;
627	}
