196	                          (int)lv_obj_get_width(s_retry),
197	                          (int)lv_obj_get_height(s_retry),
198	                          (int)b.x1, (int)b.y1,
199	                          lv_obj_has_flag(s_retry, LV_OBJ_FLAG_HIDDEN) ? 0 : 1,
200	                          lv_obj_hit_test(s_retry, &p) ? 1 : 0);
201	        }
202	
203	        if(s_close != NULL && n < (int)sizeof(buf)) {
204	            lv_obj_get_coords(s_close, &b);
205	            lv_point_t p = { (b.x1 + b.x2) / 2, (b.y1 + b.y2) / 2 };
