207	                          "overlay: close=%dx%d at %d,%d hit=%d\n",
208	                          (int)lv_obj_get_width(s_close), (int)lv_obj_get_height(s_close),
209	                          (int)b.x1, (int)b.y1, lv_obj_hit_test(s_close, &p) ? 1 : 0);
210	        }
211	    }
