222	/* Adapter from the per-tool callback to the structured trace. */
223	
224	static void trace_tool_done(void* ctx, int iteration, const char* name,
225	    uint32_t ms, size_t out_bytes, bool ok)
226	{
227	    agent_trace_tool((agent_trace_t*)ctx, iteration, name, ms, out_bytes, ok);
228	}
229	
230	/* ── Deterministic single-point reply ──────────────────────── */
231	
232	/* A question like "what is the UPS load" costs two LLM round-trips: one to
233	 * pick vg_point_read and one to restate the number the tool already
234	 * returned.  The second call exists only to reword a value that is already
235	 * decided, and it carries the same multi-second server wait as the first.
236	 *
237	 * The rendering lives in core/point_reply.c so the host test can exercise
238	 * every shape without linking the agent loop.  It returns NULL for anything
239	 * that needs wording rather than echoing, and this caller then leaves the
240	 * reply to the model as before. */
241	
242	/* Add one role:"tool" message per tool result (OpenAI format).
243	 * When call_count > 1, all tools run in parallel threads.
244	 * Uses memory pool for parallel buffers, with heap fallback.
245	 *
246	 * Each result is reported through on_tool() so the trace can record the real
247	 * tool time.  Before this, the only number near a tool name was the LLM call
248	 * time, which made a 97 s model response look like a 97 s tool. */
249	
250	typedef void (*tool_done_fn)(void* ctx, int iteration, const char* name,
251	    uint32_t ms, size_t out_bytes, bool ok);
252	
253	static void add_tool_result_messages(cJSON* messages,
254	    const llm_response_t* resp, char* tool_output,
255	    size_t tool_output_size, const char* msg_channel,
256	    const char* msg_chat_id, int iteration, tool_done_fn on_tool, void* ctx)
257	{
258	    int n = resp->call_count;
259	
260	    if (n == 1) {
261	        const llm_tool_call_t* call = &resp->calls[0];
262	        uint32_t t0;
263	        int32_t tool_ms;
264	
265	        syslog(LOG_INFO, "[%s] Tool call: %s args=%.500s\n", TAG,
266	            call->name, call->input ? call->input : "(null)");
267	        tool_output[0] = '\0';
268	        char* patched = inject_cron_context(
269	            call->name, call->input, msg_channel, msg_chat_id);
270	        t0 = agent_mono_ms();
271	        agent_tool_exec_streamed(call->name,
272	            patched ? patched : call->input,
273	            tool_output, tool_output_size);
274	        tool_ms = agent_elapsed_ms(t0, agent_mono_ms());
275	        free(patched);
276	        syslog(LOG_INFO, "[%s] Tool %s result: %d bytes, %ld ms\n", TAG,
277	            call->name, (int)strlen(tool_output), (long)tool_ms);
278	
279	        if (on_tool != NULL) {
280	            on_tool(ctx, iteration, call->name,
281	                tool_ms == AGENT_T_NA ? 0u : (uint32_t)tool_ms,
282	                strlen(tool_output), true);
283	        }
284	
285	        cJSON* result_msg = cJSON_CreateObject();
286	        cJSON_AddStringToObject(result_msg, "role", "tool");
287	        cJSON_AddStringToObject(result_msg, "tool_call_id", call->id);
288	        cJSON_AddStringToObject(result_msg, "content", tool_output);
289	        cJSON_AddItemToArray(messages, result_msg);
290	        return;
291	    }
292	
293	    /* Parallel path */
294	    tool_task_t tasks[AGENT_MAX_TOOL_CALLS];
295	    pthread_t threads[AGENT_MAX_TOOL_CALLS];
296	    size_t par_buf_size = agent_mem_safe_size(
297	        TOOL_OUTPUT_SIZE_LARGE, TOOL_OUTPUT_SIZE_MIN);
298	
299	    for (int i = 0; i < n; i++) {
300	        tasks[i].call = &resp->calls[i];
301	        strncpy(tasks[i].channel, msg_channel ? msg_channel : "",
302	            sizeof(tasks[i].channel) - 1);
303	        strncpy(tasks[i].chat_id, msg_chat_id ? msg_chat_id : "",
304	            sizeof(tasks[i].chat_id) - 1);
305	        tasks[i].elapsed_ms = AGENT_T_NA;
306	
307	        char* buf = s_pool_ready
308	            ? agent_pool_acquire(&s_tool_pool)
309	            : NULL;
310	        if (buf) {
311	            tasks[i].output = buf;
312	            tasks[i].output_size = s_tool_pool.buf_size;
313	            tasks[i].from_pool = true;
314	        } else {
315	            tasks[i].output = calloc(1, par_buf_size);
316	            tasks[i].output_size = par_buf_size;
317	            tasks[i].from_pool = false;
318	        }
319	
320	        if (!tasks[i].output) {
321	            threads[i] = 0;
322	            tasks[i].elapsed_ms = AGENT_T_NA;
323	            continue;
324	        }
325	
326	        pthread_attr_t attr;
327	        pthread_attr_init(&attr);
328	#ifdef CONFIG_VG_HMI
329	        /* Tool workers share the tight HMI heap; 16 KiB was the same
330	         * class of overflow that corrupted mm freelist on the loop
331	         * stack before AGENT_AI_AGENT_STACK was raised to 32 KiB. */
332	        pthread_attr_setstacksize(&attr, 24 * 1024);
333	#else
334	        pthread_attr_setstacksize(&attr, 16 * 1024);
335	#endif
336	        if (pthread_create(&threads[i], &attr,
337	                tool_exec_thread, &tasks[i])
338	            != 0) {
339	            syslog(LOG_ERR, "[%s] Failed to spawn thread for tool %s\n",
340	                TAG, resp->calls[i].name);
341	            threads[i] = 0;
342	        }
343	        pthread_attr_destroy(&attr);
344	    }
345	
346	    /* Join and collect results, dedup by tool_call_id */
347	    char seen_ids[AGENT_MAX_TOOL_CALLS][32];
348	    int seen_count = 0;
349	
350	    for (int i = 0; i < n; i++) {
351	        if (threads[i]) {
352	            pthread_join(threads[i], NULL);
353	        }
354	
355	        bool dup = false;
356	        for (int j = 0; j < seen_count; j++) {
357	            if (strcmp(seen_ids[j], resp->calls[i].id) == 0) {
358	                dup = true;
359	                break;
360	            }
361	        }
362	
363	        if (dup) {
364	            syslog(LOG_WARNING,
365	                "[%s] Skipping duplicate tool_call_id: %s\n",
366	                TAG, resp->calls[i].id);
367	        } else {
368	            strncpy(seen_ids[seen_count++], resp->calls[i].id,
369	                sizeof(seen_ids[0]) - 1);
370	
371	            cJSON* result_msg = cJSON_CreateObject();
372	            cJSON_AddStringToObject(result_msg, "role", "tool");
373	            cJSON_AddStringToObject(result_msg, "tool_call_id",
374	                resp->calls[i].id);
375	            cJSON_AddStringToObject(result_msg, "content",
376	                (tasks[i].output && tasks[i].output[0])
377	                    ? tasks[i].output
378	                    : "{}");
379	            cJSON_AddItemToArray(messages, result_msg);
380	
381	            /* Parallel rounds run one thread per call, so wall time and CPU
382	             * time differ; report each tool's own span and let the reader
383	             * compare them instead of summing. */
384	
385	            if (on_tool != NULL) {
386	                on_tool(ctx, iteration, resp->calls[i].name,
387	                    tasks[i].elapsed_ms == AGENT_T_NA
388	                        ? 0u
389	                        : (uint32_t)tasks[i].elapsed_ms,
390	                    tasks[i].output ? strlen(tasks[i].output) : 0u,
391	                    tasks[i].elapsed_ms != AGENT_T_NA);
392	            }
393	        }
394	
395	        if (tasks[i].from_pool) {
396	            agent_pool_release(&s_tool_pool, tasks[i].output);
397	        } else {
398	            free(tasks[i].output);
399	        }
400	    }
401	}
