404	
405	/* A/B switch for the single-point reply shortcut.  Default on: the board
406	 * measurement (2026-10-20, docs/maintenance-evidence/2026-10-20/
407	 * rsp03-shortcut-ab.md) showed 1 request instead of 2-4 for a hit, a median
408	 * round of 5.82 s against 10.68 s, and 11/11 correct values, with every
409	 * explanation, multi-point, stale, offline and ambiguous round still falling
410	 * through to the model.  The NSH command "point_shortcut off" restores the
411	 * two-request path so a regression can be re-measured without a reflash.
412	 * Not persisted: a reboot restores the default. */
413	
414	static volatile bool s_point_reply_disabled = false;
415	
416	void agent_point_reply_set_enabled(bool enabled)
417	{
418	    s_point_reply_disabled = !enabled;
419	
420	    /* Both arms receive the same user message, so a response cached under
421	     * one arm would be replayed verbatim under the other and hide the effect
422	     * under test.  The cache also bypasses the model completely, which turns
423	     * a two-request round into a zero-request one.  Dropping it on every
424	     * switch keeps each measured round honest. */
425	
426	    llm_cache_cleanup();
427	
428	    syslog(LOG_INFO, "[%s] point reply shortcut %s\n", TAG,
429	        enabled ? "enabled" : "disabled");
430	}
431	
432	bool agent_point_reply_enabled(void)
433	{
434	    return !s_point_reply_disabled;
435	}
