static size_t status_append(char *out, size_t cap, size_t off,
                            const char *fmt, ...)
{
  va_list ap;
  int n;

  if (out == NULL || cap == 0 || off >= cap - 1)
    {
      return off;
    }

  va_start(ap, fmt);
  n = vsnprintf(out + off, cap - off, fmt, ap);
  va_end(ap);

  if (n < 0)
    {
      return off;
    }

  off += (size_t)n;
  return (off < cap) ? off : cap - 1;
}

