```c
static bool vr_build_request(char *question, size_t qcap)
{
  const char *text = g_vr.s.text;
  size_t off = 0;

  if (text == NULL || text[0] == '\0') return false;

  if (g_vr.ctx_ms != 0 &&
      (int32_t)(vr_now_ms() - g_vr.ctx_ms) >= 0 &&
      vr_now_ms() - g_vr.ctx_ms < VG_VS_IDLE_MS &&
      (g_vr.ctx_question[0] != '\0' || g_vr.ctx_answer[0] != '\0'))
    {
      off += snprintf(question+off, qcap-off, "上一问:%s\n上一答:%s\n",
                      g_vr.ctx_question, g_vr.ctx_answer);
      if (off >= qcap) return false;  // bounded: fallthrough guard
    }

  snprintf(question+off, qcap-off, "用户本次提问:%s", text);
  return true;
}
```

上下文时效判断:vr_now_ms() - ctx_ms < VG_VS_IDLE_MS(5分钟)。wrap-safe: (int32_t)(now - ctx) >= 0 && (uint32_t)(now-ctx) < IDLE。简单起见用 (int32_t) 转换比较一次。

